#!/bin/sh
# @NAME@ — the portfolio as a terminal app.      @CMD@
#
# Generated by scripts/build-site.mjs from scripts/tui.template.sh and /content.
# It installs nothing unless you ask it to (D, then y): it draws to your terminal and, when you
# press enter on something, opens that link in your browser. POSIX sh + awk + stty only.
#
#   up/down or j/k  move        left/right, l, tab or 1-5  switch section
#   enter or o      open        g / G  first / last     q  quit
#   h or ?          every control, in words (the legend shows only the keys after a moment)
#   t / T           time machine: pick a day or type a date / back to the present
#   s               seasonal effects on or off (WEMILLER_SEASONS=0)
#   /               search everything, enter jumps to the match
#   r               download the resume as a PDF into the folder you ran this from
#                   (Markdown instead if the download fails)
#   m               music: a little radio composes synthwave, lo-fi and rock as it plays. It is
#                   written in awk right here and downloads nothing; the sound goes to the player
#                   your system already has (afplay, pw-play, paplay or aplay) through a
#                   temporary folder that it removes when you turn it off or quit.
#   - / +           music volume down / up (0-10; WEMILLER_VOLUME sets where it starts)
#   L               next language
#   D               install my dotfiles (wemiller.com/dotfiles) for the user running this. It asks
#                   first and does nothing unless you press y: it saves ~/.zshlocal (or
#                   ~/.ashlocal where there is no zsh or bash) and adds one line to your shell
#                   startup files so new shells load it.
#
# It speaks English, 简体中文, 日本語, Deutsch, Français, Español, 한국어, Português and Italiano:
# WEMILLER_LANG=ja (or any of zh, ja, de, fr, es, ko, pt, it, en) picks one, otherwise your locale
# does (LC_ALL, LC_MESSAGES, LANG). A terminal that is not UTF-8 gets English in plain ASCII.
set -u

data() { cat <<'WM_DATA'
@DATA@
WM_DATA
}

PROG=$(cat <<'WM_AWK'
function at(r, c) { return ESC "[" r ";" c "H" }
function rep(s, n,   o) { o = ""; while (n-- > 0) o = o s; return o }

# ---- text width ----
# awk always runs with LC_ALL=C, so every awk (BSD, mawk, busybox, gawk) sees bytes. UTF-8 is
# decoded here, and widths are terminal columns: CJK and full-width characters take two.
function uinit(   i) {
  for (i = 1; i < 256; i++) ORD[sprintf("%c", i)] = i
  HI = "["; for (i = 128; i < 256; i++) HI = HI sprintf("%c", i); HI = HI "]"
  NOSTART = "、。，．：；？！）」』】〕〉》｝ー々ゝゞぁぃぅぇぉっゃゅょァィゥェォッャュョ…・"
  NOEND = "（「『【〔〈《｛"
  CLOSE1 = ",.;:!?)]}%"
  # the small search pictures: one character a pixel, 4 levels each of red, green and blue
  split("0 1 3 5", LV4, " ")
  for (i = 0; i < 64; i++) CHX[substr("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz+/", i + 1, 1)] = 16 + 36 * LV4[int(i / 16) + 1] + 6 * LV4[int(i / 4) % 4 + 1] + LV4[i % 4 + 1]
}
# the width of the character at byte i of s (-1: a broken sequence); CLEN gets its length in bytes
function cw(s, i,   b, c, n, k, x) {
  b = ORD[substr(s, i, 1)]; CLEN = 1
  if (b < 128) return b < 32 ? 0 : 1
  if (b < 194 || b > 244) return -1
  if (b < 224) { n = 2; c = b - 192 } else if (b < 240) { n = 3; c = b - 224 } else { n = 4; c = b - 240 }
  for (k = 1; k < n; k++) {
    x = ORD[substr(s, i + k, 1)]
    if (x < 128 || x > 191) { CLEN = k; return -1 }
    c = c * 64 + x - 128
  }
  CLEN = n; CP = c
  if (c < 768) return 1
  if (c <= 879) return 0                      # combining accents
  if (c < 4352) return 1
  if (c <= 4447) return 2                     # Hangul jamo
  if (c >= 8203 && c <= 8207) return 0        # zero-width space and joiners
  if (c < 11904) return 1
  if (c <= 42191) return c == 12351 ? 1 : 2   # CJK radicals, kana, ideographs, Yi
  if (c >= 43360 && c <= 43391) return 2
  if (c >= 44032 && c <= 55203) return 2      # Hangul syllables
  if (c >= 63744 && c <= 64255) return 2
  if (c >= 65024 && c <= 65039) return 0      # variation selectors
  if (c >= 65040 && c <= 65049) return 2
  if (c >= 65072 && c <= 65135) return 2
  if (c >= 65280 && c <= 65376) return 2      # full-width forms
  if (c >= 65504 && c <= 65510) return 2
  if (c >= 127744 && c <= 128591) return 2    # emoji
  if (c >= 129280 && c <= 129535) return 2
  if (c >= 131072 && c <= 262141) return 2
  return 1
}
function dwidth(s,   i, n, w, x) {
  if (s !~ HI) return length(s)
  n = length(s); w = 0
  for (i = 1; i <= n; i += CLEN) { x = cw(s, i); if (x > 0) w += x }
  return w
}
# the longest start of s that fits in w columns, never half a character; TW gets its width
function fit(s, w,   i, n, x, o, t) {
  if (s !~ HI) { o = substr(s, 1, w > 0 ? w : 0); TW = length(o); return o }
  n = length(s); o = ""; t = 0
  for (i = 1; i <= n; i += CLEN) {
    x = cw(s, i)
    if (x < 0) continue
    if (t + x > w) break
    o = o substr(s, i, CLEN); t += x
  }
  TW = t; return o
}
function pad(s, w) { s = fit(s, w); return s rep(" ", w - TW) }
# Units a line may break between: words, and each Chinese or Japanese character on its own
# (those scripts use no spaces). TK[i] is the unit, TKW[i] its width, TKS[i] 1 when a space comes before it.
function tok(t,   n, i, L, x, ch, cur, curw, cursp, sp, open, k, a) {
  n = 0
  if (t !~ HI) {
    k = split(t, a, " ")
    for (i = 1; i <= k; i++) if (a[i] != "") { n++; TK[n] = a[i]; TKW[n] = length(a[i]); TKS[n] = 1 }
    return n
  }
  cur = ""; curw = 0; cursp = 0; sp = 0; open = 0; L = length(t)
  for (i = 1; i <= L; i += CLEN) {
    x = cw(t, i); ch = substr(t, i, CLEN)
    if (x < 0) continue
    if (ch == " ") {
      if (cur != "") { n++; TK[n] = cur; TKW[n] = curw; TKS[n] = cursp; cur = ""; curw = 0; open = 0 }
      sp = 1; continue
    }
    # Korean puts spaces between words, so Hangul stays whole like a Latin word
    if (x == 2 && !(CP >= 44032 && CP <= 55203) && !(CP >= 4352 && CP <= 4447) && !(CP >= 12593 && CP <= 12686)) {
      if (!sp && index(NOSTART, ch)) {         # closing marks stay with what came before
        if (cur != "") { cur = cur ch; curw += 2 }
        else if (n > 0) { TK[n] = TK[n] ch; TKW[n] += 2 }
        else { cur = ch; curw = 2; cursp = 0 }
        continue
      }
      if (index(NOEND, ch)) {                  # opening marks go with what comes after
        if (cur != "" && !open) { n++; TK[n] = cur; TKW[n] = curw; TKS[n] = cursp; cur = ""; curw = 0 }
        if (cur == "") { cursp = sp; sp = 0 }
        cur = cur ch; curw += 2; open = 1; continue
      }
      if (open) { cur = cur ch; curw += 2; n++; TK[n] = cur; TKW[n] = curw; TKS[n] = cursp; cur = ""; curw = 0; open = 0; continue }
      if (cur != "") { n++; TK[n] = cur; TKW[n] = curw; TKS[n] = cursp; cur = ""; curw = 0 }
      n++; TK[n] = ch; TKW[n] = 2; TKS[n] = sp; sp = 0; continue
    }
    if (cur == "" && !sp && n > 0 && index(CLOSE1, ch)) { TK[n] = TK[n] ch; TKW[n] += x; continue }
    if (cur == "") { cursp = sp; sp = 0 }
    cur = cur ch; curw += x; open = 0
  }
  if (cur != "") { n++; TK[n] = cur; TKW[n] = curw; TKS[n] = cursp }
  return n
}
function wrap(t, w,   n, i, k, line, lw, s, x, p) {
  n = 0; k = tok(t); line = ""; lw = 0
  for (i = 1; i <= k; i++) {
    s = line == "" ? 0 : TKS[i]
    if (line != "" && lw + s + TKW[i] > w) { WR[++n] = line; line = ""; lw = 0; s = 0 }
    if (TKW[i] > w) {                          # wider than the line: cut it, at a character
      x = TK[i]
      while (dwidth(x) > w) { p = fit(x, w); if (p == "") break; WR[++n] = p; x = substr(x, length(p) + 1) }
      line = x; lw = dwidth(x); continue
    }
    line = line (s ? " " : "") TK[i]; lw += s + TKW[i]
  }
  if (line != "") WR[++n] = line
  return n
}
# a translated string with {1} and {2} filled in
function fmt(s, a, b,   p) {
  if ((p = index(s, "{1}")) > 0) s = substr(s, 1, p - 1) a substr(s, p + 3)
  if ((p = index(s, "{2}")) > 0) s = substr(s, 1, p - 1) b substr(s, p + 3)
  return s
}
# a status message from the shell or the music process: "%key|arg|arg"
function msg(m,   a, n) {
  if (substr(m, 1, 1) != "%") return m
  n = split(substr(m, 2), a, "|")
  return ("m." a[1]) in U ? fmt(U["m." a[1]], a[2], a[3]) : m
}
# a key legend: " key word  key word", the words in the current language
function legend(list, gap,   n, a, i, s) {
  n = split(list, a, " "); s = ""
  for (i = 1; i <= n; i++) s = s (i == 1 ? " " : gap) (HK[a[i]] == "" ? "" : HK[a[i]] " ") U["h." a[i]]
  return s
}
# ---- the calendar: the same days the site keeps (content/site.json → seasons, luma, future) ----
function mod(a, b) { return ((a % b) + b) % b }
function dnum(y, m, d,   era, yoe, doy) {                   # days since 1970-01-01
  y -= (m <= 2); era = int((y >= 0 ? y : y - 399) / 400); yoe = y - era * 400
  doy = int((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1
  return era * 146097 + yoe * 365 + int(yoe / 4) - int(yoe / 100) + doy - 719468
}
function dofs(s) { return dnum(substr(s, 1, 4) + 0, substr(s, 6, 2) + 0, substr(s, 9, 2) + 0) }
function dstr(z,   era, doe, yoe, y, doy, mp, d, m) {
  z += 719468; era = int((z >= 0 ? z : z - 146096) / 146097); doe = z - era * 146097
  yoe = int((doe - int(doe / 1460) + int(doe / 36524) - int(doe / 146096)) / 365)
  y = yoe + era * 400; doy = doe - (365 * yoe + int(yoe / 4) - int(yoe / 100)); mp = int((5 * doy + 2) / 153)
  d = doy - int((153 * mp + 2) / 5) + 1; m = mp + (mp < 10 ? 3 : -9); y += (m <= 2)
  return sprintf("%04d-%02d-%02d", y, m, d)
}
function isdate(s) { return s ~ /^[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]$/ && substr(s, 1, 4) + 0 >= 1000 && dstr(dofs(s)) == s }
function addy(n, years,   s, y) {                           # the same day, some years later
  s = dstr(n); y = sprintf("%04d", substr(s, 1, 4) + years)
  return isdate(y substr(s, 5)) ? dofs(y substr(s, 5)) : dofs(y substr(s, 5, 4) "28")
}
function easter(yr,   a, b, c, d, e, f, g, h, i, k, l, m) {   # Gregorian computus
  a = yr % 19; b = int(yr / 100); c = yr % 100; d = int(b / 4); e = b % 4; f = int((b + 8) / 25); g = int((b - f + 1) / 3)
  h = (19 * a + b - d - g + 15) % 30; i = int(c / 4); k = c % 4; l = (32 + 2 * e + 2 * i - h - k) % 7; m = int((a + 11 * h + 22 * l) / 451)
  return dnum(yr, int((h + l - 7 * m + 114) / 31), (h + l - 7 * m + 114) % 31 + 1)
}
function memorial(yr,   n) { n = dnum(yr, 5, 31); return n - mod(n + 3, 7) }   # the last Monday of May
# A named day means its most recent occurrence (as on the site), so a celebration can be replayed.
function lastof(id,   j, k, d, y) {
  j = ZI[id]
  if (id != "luma" && !j) return ""
  if (j && ZDATE[j] != "") return dofs(ZDATE[j])
  y = substr(today, 1, 4) + 0
  for (k = 0; k < 2; k++) {
    if (id == "luma") d = dofs(sprintf("%04d", y - k) substr(S["luma_born"], 5))
    else if (ZRULE[j] == "easter") d = easter(y - k)
    else if (ZRULE[j] == "memorial") d = memorial(y - k)
    else d = dofs(sprintf("%04d", y - k) "-" (ZDAY[j] != "" ? ZDAY[j] : ZFROM[j]))
    if (d <= TN) return d
  }
  return d
}
function resolve(w,   d) {
  if (w == "" || w == "now") return TN
  if (isdate(w)) return dofs(w)
  d = lastof(w)
  return d == "" ? TN : d
}
# the season of the destination day (the first that matches, as on the site), and whether it is the day itself
function season(   j, md, y, base, f, t) {
  md = substr(D, 6, 5); y = substr(D, 1, 4) + 0; ONDAY = 0
  for (j = 1; j <= nz; j++) {
    if (ZDATE[j] != "") { if (ZDATE[j] == D) { ONDAY = 1; return j } continue }
    if (ZRULE[j] != "") {
      base = ZRULE[j] == "easter" ? easter(y) : memorial(y)
      if (DN >= base - ZB[j] && DN <= base + ZA[j]) { ONDAY = (DN == base); return j }
      continue
    }
    f = ZFROM[j]; t = ZTO[j]
    if (f <= t ? (md >= f && md <= t) : (md >= f || md <= t)) {
      ONDAY = (md == (ZDAY[j] != "" ? ZDAY[j] : ZFROM[j])) || (ZDAY[j] == "" && ZFROM[j] == ZTO[j])
      return j
    }
  }
  return 0
}

# ---- the time machine: the destination day decides what exists ----
function timemachine(   i, k, month, start, n, y, list, nl, skipped, g, last, qall, qluma, q120, removed, id) {
  TN = dofs(today); DN = resolve(when); D = dstr(DN); TY = substr(today, 1, 4) + 0; DY = substr(D, 1, 4) + 0
  travel = DN != TN; past = DN < TN; future = DN > TN
  founder = S["founder_from"] != "" && D >= S["founder_from"]
  if (travel) ghyear()                        # GitHub: the year that ends on the destination day
  for (i = 1; i <= np; i++) PO[i] = i
  for (i = 1; i <= nf; i++) FO[i] = i
  if (past) {                                 # take away what had not happened yet
    month = substr(D, 1, 7); k = 0
    for (i = 1; i <= np; i++) if (substr(PD[i], 1, 7) <= month) {
      k++; PT[k] = PT[i]; PD[k] = PD[i]; PG[k] = PG[i]; PU[k] = PU[i]; PS[k] = PS[i]; PX[k] = PX[i]; PL[k] = PL[i]; PO[k] = PO[i]
    }
    np = k; k = 0
    for (i = 1; i <= nj; i++) if (substr(JW[i], 4, 4) "-" substr(JW[i], 1, 2) <= month) {
      k++; JR[k] = JR[i]; JC[k] = JC[i]; JW[k] = JW[i]; JP[k] = JP[i]; JF[k] = JF[i]; JB[k] = JB[i]
    }
    nj = k; k = 0
    for (i = 1; i <= ne; i++) if (EB[i] == "" || EB[i] <= month) { k++; ET[k] = ET[i]; ES[k] = ES[i]; EB[k] = EB[i] }
    ne = k; k = 0
    for (i = 1; i <= nf; i++) if (FD[i] == "" || FD[i] <= D) { k++; FT[k] = FT[i]; FU[k] = FU[i]; FD[k] = FD[i]; FA[k] = FA[i]; FO[k] = FO[i] }
    nf = k
    for (i = 1; i <= nq; i++) if (QD[i] == "" || QD[i] <= D) { qall++; qluma += QL[i]; q120 += QS[i] }
    removed = nq - qall
    for (id = 1; id <= 6; id++) {             # the photographs on the Photography tab, too
      k = 0
      for (i = 1; i <= ni[id]; i++) if (ID[id, i] == "" || ID[id, i] <= D) {
        k++; IW[id, k] = IW[id, i]; IH[id, k] = IH[id, i]; IP[id, k] = IP[id, i]; IC[id, k] = IC[id, i]; ID[id, k] = ID[id, i]
      }
      ni[id] = k
    }
    k = 0; for (i = 1; i <= ny; i++) if (YY[i] + 0 <= DY) k++
    ny = k
    NV[1] = np >= 5 ? int(np / 5) * 5 : np; NV[2] -= removed; if (NV[2] < 0) NV[2] = 0
    NV[3] -= TY - DY; if (NV[3] < 0) NV[3] = 0
    NV[4] = np; NV[6] = qluma
    HN[1] = qall; HN[2] = q120; HN[3] = qluma
  }
  if (future && DY > TY) {                    # work still to come: unreadable, newest first
    nl = 0
    for (y = TY + 1; y <= TY + 2 && y <= DY - 1; y++) list[++nl] = y
    last = nl ? list[nl] : TY
    skipped = DY - last > 1
    n = 0
    GHY[++n] = DY
    if (skipped) GHY[++n] = "gap"
    for (i = nl; i >= 1; i--) GHY[++n] = list[i]
    k = 0
    for (i = 1; i <= n; i++) {
      if (GHY[i] == "gap") { k++; GK[k] = 2; GD[k] = (last + 1) "-" (DY - 1); continue }
      for (g = 0; g < 1 + (GHY[i] * 7) % 3; g++) { k++; GK[k] = 1; GD[k] = GHY[i]; GN[k] = 7 + (GHY[i] + g * 5) % 8 }
      if (i == 1 && !skipped) { k++; GK[k] = 2; GD[k] = "" }
    }
    for (i = np; i >= 1; i--) {                # make room at the top of the list
      PT[i + k] = PT[i]; PD[i + k] = PD[i]; PG[i + k] = PG[i]; PU[i + k] = PU[i]; PS[i + k] = PS[i]; PX[i + k] = PX[i]; PL[i + k] = PL[i]; PO[i + k] = PO[i]
    }
    for (i = 1; i <= k; i++) {
      PGH[i] = GK[i]; PD[i] = GD[i]; PL[i] = GD[i]; PU[i] = ""; PS[i] = ""; PG[i] = ""; PO[i] = 0; PTL[i] = GN[i]
      PT[i] = GK[i] == 2 ? U["fut.unwritten"] : ""; PX[i] = U["fut.unwritten.p"]
    }
    for (i = k + 1; i <= np + k; i++) PGH[i] = 0
    np += k
  }
  if (future) dogs()
  if (founder) {                              # carried on by others, with a note from the founder
    S["eyebrow"] = U["fut.founder.eyebrow"]; S["tagline"] = U["fut.founder.h"]; S["lede"] = U["fut.founder.p"]
    S["name_upper"] = toupper(S["host"]); BIG = "WEMILLER"
  }
}
# The 53 weeks of GitHub ending on the destination day, from the cached calendar years; the
# future has not been written, and before the account there is nothing to show.
function ghyear(   start, n, y, ny0, ch, idx) {
  if (future) { GHM = "future"; nw = 53; return }
  if (wfirst == "" || DY < wfirst + 0) { GHM = "none"; nw = 0; return }
  GHM = "past"; GW = ""; nw = 53
  start = DN - mod(DN + 4, 7) - 52 * 7         # the first column starts on a Sunday
  y = substr(dstr(start), 1, 4) + 0; ny0 = dnum(y + 1, 1, 1)
  for (n = start; n < start + 53 * 7; n++) {
    if (n >= ny0) { y++; ny0 = dnum(y + 1, 1, 1) }
    if (n > DN) { GW = GW "."; continue }
    ch = (y "") in WL ? substr(WL[y ""], n - dnum(y, 1, 1) + 1, 1) : "."
    GW = GW (ch == "" ? "." : ch)
  }
  GT = WT[DY ""]
}
# The dogs of the destination year: Luma (and any real dogs), then stand-ins. Each lives about
# twelve years; the next arrives when the current one is six, never sooner than a year from today.
function dogs(   a, b, n, i, k, nx, soon, round, nm, life, adopt, who, R) {
  life = S["dog_life"] + 0; adopt = S["dog_adopt"] + 0; nd = 0
  if (S["luma_born"] != "") { nd++; DGN[nd] = "Luma"; DGB[nd] = dofs(S["luma_born"]); DGE[nd] = S["luma_passed"] != "" ? dofs(S["luma_passed"]) : addy(DGB[nd], life); DGR[nd] = 1 }
  n = split(S["dog_real"], a, ",")
  for (i = 1; i <= n; i++) if (split(a[i], b, "/") >= 2) { nd++; DGN[nd] = b[1]; DGB[nd] = dofs(b[2]); DGE[nd] = b[3] != "" ? dofs(b[3]) : addy(DGB[nd], life); DGR[nd] = 1 }
  k = split(S["dog_names"], nm, ",")
  split("II III IV V VI VII VIII IX X", R, " ")
  if (nd && k) {
    nx = addy(DGB[nd], adopt); soon = addy(TN, 1); if (nx < soon) nx = soon
    for (n = 0; nx <= DN && n < 400; n++) {
      round = int(n / k); nd++
      DGN[nd] = nm[n % k + 1] (round ? " " R[round > 9 ? 9 : round] : ""); DGB[nd] = nx; DGE[nd] = addy(nx, life); DGR[nd] = 0
      nx = addy(nx, adopt)
    }
  }
  nal = ngo = 0; lumahere = 0
  for (i = 1; i <= nd; i++) {
    if (DGB[i] <= DN && DN < DGE[i]) { AL[++nal] = i; if (DGR[i] && DGN[i] == "Luma") lumahere = 1 }
    else if (DGE[i] <= DN) GO[++ngo] = i
  }
  dogchanged = ngo || nal != 1 || !DGR[AL[1]]
  if (!dogchanged) return
  who = ""; for (i = 1; i <= nal; i++) who = who (i > 1 ? " & " : "") DGN[AL[i]]
  if (who == "" && ngo) who = DGN[GO[ngo]]
  HL[3] = who; HX[3] = U["fut.dogs.p"]
  if ((i = index(HX[3], "{year}")) > 0) HX[3] = substr(HX[3], 1, i - 1) DY substr(HX[3], i + 6)
  if (!lumahere) { HN[3] = ""; if (nn >= 6) nn = 5 }
  ghostdogs = !lumahere
}
# unreadable text, a few characters of it changing every frame
function scr(n, seed,   s, i, k) {
  s = ""
  for (i = 1; i <= n; i++) { k = (seed * 7 + i * 13 + int((tick + (seed + i) % 4) / 3) * ((i % 3) + 1) * 5) % NG; s = s GL[k + 1] }
  return s
}
# a placeholder where a picture will be: a framed field of block characters in a few colours
function glitch(r0, c0, w, h, seed,   y, x, line, k, col, P) {
  if (w < 6 || h < 3) return 0
  split(seed % 2 ? "141 75 117 183" : "99 213 111 159", P, " ")
  o = o at(r0, c0) C_FR TL rep(H, w - 2) TR RST
  for (y = 1; y < h - 1; y++) {
    line = at(r0 + y, c0) C_FR V RST
    for (x = 1; x < w - 1; x++) {
      k = (x * 7 + y * 13 + seed * 5 + int((tick + x * y) / 4) * 3) % NG
      col = P[int((x * 4) / w) % 4 + 1]
      line = line (color ? ESC "[38;5;" col "m" : "") GL[k + 1]
    }
    o = o line RST C_FR V RST
  }
  o = o at(r0 + h - 1, c0) C_FR BL rep(H, w - 2) BR RST
  return h
}

# ---- the seasons: an accent colour, a little weather, a greeting on the day ----
# Same calendar as the site, read for the destination day. Cheap: a handful of characters that
# move with the frame clock, only in space nothing else uses. Off with s or WEMILLER_SEASONS=0.
function seasons(   e, id) {
  SZ = (fx && !founder) ? season() : 0
  if (!SZ) return
  e = ZEF[SZ]; id = ZID[SZ]; EF = e
  # xterm-256 palettes after the site's; no yellow or gold except New Year's fireworks
  if (e == "snow") { ACC = 153; FXP = "231 195 153" }
  else if (e == "leaves") { ACC = 173; FXP = "130 166 173 94" }
  else if (e == "fireflies") { ACC = 114; FXP = "157 121 158" }
  else if (e == "embers") { ACC = 141; FXP = "141 208 99" }
  else if (e == "petals") { ACC = 218; FXP = "218 153 183 158" }
  else if (e == "stars") { ACC = 111; FXP = "231 203 69" }
  else if (e == "confetti") { ACC = 85; FXP = "79 75 211 231 147" }
  else { ACC = 75; FXP = "75 203 231 121 183" }
  if (id == "newyear") { ACC = 231; FXP = "231 231 221 203" }
  if (id == "july4" || id == "america250") { ACC = 203; FXP = "231 196 69" }
  NFP = split(FXP, FPC, " ")
  if (utf) {
    if (e == "snow") FXG = "* · • ·"; else if (e == "leaves") FXG = "❧ ❦ ⸙ ❧"; else if (e == "fireflies") FXG = "• · • ·"
    else if (e == "embers") FXG = "˚ · • ˙"; else if (e == "petals") FXG = "✿ ❀ · ✿"; else if (e == "stars") FXG = "✦ ✧ · ✦"
    else if (e == "confetti") FXG = "▪ ▫ • ◆"; else FXG = "* + · ✦"
  } else FXG = e == "snow" ? "* . * ." : "* + . o"
  NFG = split(FXG, FGL, " ")
  GREET = (ZGR[SZ] && ONDAY) ? U["g." id] : ""
}
function fxcol(j) { return color ? ESC "[38;5;" FPC[j % NFP + 1] "m" : "" }
# little weather in a box of the screen: falling, rising, blinking or bursting, by the effect
function motif(r0, c0, r1, c1,   w, h, j, n, x, y, cx, cy, ph, a, k) {
  w = c1 - c0 + 1; h = r1 - r0 + 1
  if (!SZ || w < 8 || h < 2) return
  n = int(w * h / 14) + 2
  if (EF == "fireworks") {                      # a burst every few seconds, somewhere new
    for (k = 0; k < 2; k++) {
      ph = (tick + k * 9) % 18; cx = c0 + (int((tick + k * 9) / 18) * 13 + k * 7) % w; cy = r0 + (int((tick + k * 9) / 18) * 5 + k) % h
      if (ph > 6) continue
      for (a = 0; a < 8; a++) {
        x = cx + int(ph * (a == 0 || a == 4 ? 0 : a < 4 ? 2 : -2)); y = cy + int(ph * (a == 2 || a == 6 ? 0 : (a < 2 || a > 6) ? -0.5 : 0.5))
        if (x >= c0 && x <= c1 && y >= r0 && y <= r1) o = o at(y, x) fxcol(a + k) (ph < 3 ? FGL[1] : FGL[3]) RST
      }
    }
    return
  }
  for (j = 1; j <= n; j++) {
    x = c0 + (j * 37 + (EF == "fireflies" ? 0 : int((tick + j) / 3) * (j % 3 - 1))) % w; if (x < c0) x += w
    if (EF == "embers") y = r1 - (j * 11 + tick) % h
    else if (EF == "fireflies") { y = r0 + (j * 7) % h; if ((tick + j * 3) % 8 > 4) continue }
    else y = r0 + (j * 11 + int(tick * (1 + j % 2) / 2)) % h
    o = o at(y, x) fxcol(j) FGL[j % NFG + 1] RST
  }
}
# Christmas lights along the line under the tabs: five colours, a chase that moves with the clock
function lights(r, c0, c1,   x, i, cols5, on) {
  if (!SZ || !ZLT[SZ]) return
  split("196 41 33 231 213", cols5, " ")
  i = 0
  for (x = c0 + 2; x <= c1 - 1; x += 4) {
    on = (i + int(tick / 2)) % 5 < 3
    if (x == split_col) x++
    o = o at(r, x) (color ? ESC "[" (on ? "1;" : "2;") "38;5;" cols5[i % 5 + 1] "m" : "") (utf ? "●" : "o") RST
    i++
  }
}
# The time machine's picker: back to the present, the named days, or a typed date
function pickitems(   a, n, i) {
  npk = 0
  if (travel) { PKI[++npk] = "now"; PKL[npk] = U["tm.now"]; PKD[npk] = today }
  n = split("newyear easter memorial birthday july4 summer fall halloween luma veterans christmas", a, " ")
  for (i = 1; i <= n; i++) { PKI[++npk] = a[i]; PKL[npk] = U["tm.d." a[i]]; PKD[npk] = dstr(resolve(a[i])) }
}
function picker(   w, h, r0, c0, i, n, r, style, first, shown, lab) {
  pickitems()
  w = cols - 8; if (w > 60) w = 60
  n = wrap(U["tm.p"], w - 4); if (n > 2) n = 2
  shown = npk; if (shown > rows - 10 - n) shown = rows - 10 - n; if (shown < 3) shown = 3
  h = shown + n + 7 + (travel ? 1 : 0)
  r0 = int((rows - h) / 2) + 1; if (r0 < 2) r0 = 2; c0 = int((cols - w) / 2) + 1
  o = o at(r0, c0) C_AC TL rep(H, w - 2) TR RST
  for (r = r0 + 1; r < r0 + h - 1; r++) o = o at(r, c0) C_AC V RST rep(" ", w - 2) C_AC V RST
  o = o at(r0 + h - 1, c0) C_AC BL rep(H, w - 2) BR RST
  r = r0 + 1
  o = o at(r, c0 + 2) C_B pad(U["tm.title"], w - 4) RST; r++
  for (i = 1; i <= n; i++) { o = o at(r, c0 + 2) C_DIM pad(WR[i], w - 4) RST; r++ }
  if (travel) { o = o at(r, c0 + 2) C_TE pad(U["tm.dest"] ": " D, w - 4) RST; r++ }
  r++
  first = psel - int(shown / 2); if (first > npk - shown) first = npk - shown; if (first < 0) first = 0
  for (i = first + 1; i <= first + shown && i <= npk; i++) {
    style = (i == psel + 1 && td == "") ? C_SEL : C_TX
    lab = pad(" " PKL[i], w - 18)
    o = o at(r, c0 + 2) style lab " " pad(PKD[i], 12) " " RST; r++
  }
  r++
  o = o at(r, c0 + 2) C_AC fit(U["tm.pick"], w - 20) RST " " (td == "" ? C_DIM "YYYY-MM-DD" RST : C_SEL " " td "_ " RST)
}
# The warp between two days: the date runs from where you were to where you are going, and the
# screen streaks past. A dozen frames; any key skips it.
function warpview(   k, n, f, from, z, r, x, len, c, s, t, bw, bh, r0, c0, col) {
  n = 12; k = warp; f = k / n; f = f * f * (3 - 2 * f)
  from = resolve(wfrom); z = int(from + (DN - from) * f + 0.5)
  o = ESC "[2J"
  for (r = 2; r < rows; r++) {
    len = int((r * 7 + k * 3) % 11) + 2 + k
    x = int(cols / 2 + ((r % 2) ? 1 : -1) * ((r * 13 + k * (4 + r % 5)) % int(cols / 2)))
    if (x < 1) x = 1; if (x + len > cols) len = cols - x
    col = color ? ESC "[38;5;" (DN >= from ? (r % 3 ? 117 : 141) : (r % 3 ? 213 : 111)) "m" : ""
    if (len > 0) o = o at(r, x) col rep(r % 4 ? H : SCAN, len) RST
  }
  s = " " U["tm.title"] " "; t = " " dstr(z) " "
  bw = (dwidth(s) > dwidth(t) ? dwidth(s) : dwidth(t)) + 6; bh = 4
  r0 = int(rows / 2) - 1; c0 = int((cols - bw) / 2) + 1
  o = o at(r0, c0) C_AC TL rep(H, bw - 2) TR RST
  o = o at(r0 + 1, c0) C_AC V RST C_DIM pad("  " s, bw - 2) RST C_AC V RST
  o = o at(r0 + 2, c0) C_AC V RST C_B pad("  " t, bw - 2) RST C_AC V RST
  o = o at(r0 + 3, c0) C_AC BL rep(H, bw - 2) BR RST
  printf "%s", o
}

# On the way out, after the full screen is gone: the verse from the home page on a small card,
# sized to the terminal, its border in the accent colour.
function card(   w, m, n, i, tw, top_, bot_, mark, pad_, ref, inner) {
  w = cols - 4; if (w > 72) w = 72
  if (w < 24 || S["verse"] == "") return
  m = rep(" ", int((cols - w) / 2)); inner = w - 2
  mark = utf ? " ✦ " : " * "
  top_ = int((inner - dwidth(mark)) / 2)
  print ""
  print m C_AC TL rep(H, top_) RST C_B mark RST C_AC rep(H, inner - top_ - dwidth(mark)) TR RST
  print m C_AC V RST rep(" ", inner) C_AC V RST
  n = wrap(S["verse"], inner - 6)
  for (i = 1; i <= n; i++) {
    tw = dwidth(WR[i]); pad_ = int((inner - tw) / 2)
    print m C_AC V RST rep(" ", pad_) C_TX WR[i] RST rep(" ", inner - pad_ - tw) C_AC V RST
  }
  print m C_AC V RST rep(" ", inner) C_AC V RST
  ref = (utf ? "— " : "- ") S["verse_ref"]; tw = dwidth(ref); pad_ = int((inner - tw) / 2)
  print m C_AC V RST rep(" ", pad_) C_DIM ref RST rep(" ", inner - pad_ - tw) C_AC V RST
  # a horizon along the bottom: a few stars over the line
  bot_ = ""
  for (i = 1; i <= inner; i++) bot_ = bot_ ((i * 7) % 23 == 3 ? (utf ? "·" : ".") : (i * 11) % 31 == 5 ? (utf ? "˚" : "'") : " ")
  print m C_AC V RST C_DIM bot_ RST C_AC V RST
  print m C_AC BL rep(H, inner) BR RST
}
# Every control and what it does, over the screen: one column when it fits, two otherwise.
function helpview(   n, i, k, w, h, r0, c0, nc_, per, colw, kw, x, y, lab, key) {
  n = split("move section search open music vol resume tm" (travel ? " now" : "") " fx lang dot help quit", k, " ")
  HK["help"] = "h ?"; U["h.help2"] = U["h.help"]
  kw = 6
  for (i = 1; i <= n; i++) { KEYT[i] = k[i] == "open" ? "enter" : k[i] == "help" ? "h ? esc" : HK[k[i]]; if (dwidth(KEYT[i]) + 2 > kw) kw = dwidth(KEYT[i]) + 2 }
  nc_ = (n + 4 <= rows - 4) ? 1 : 2
  per = int((n + nc_ - 1) / nc_)
  w = cols - 6; if (w > (nc_ == 1 ? 56 : 92)) w = nc_ == 1 ? 56 : 92
  colw = int((w - 4) / nc_)
  h = per + 4; if (h > rows - 2) h = rows - 2
  r0 = int((rows - h) / 2) + 1; if (r0 < 2) r0 = 2; c0 = int((cols - w) / 2) + 1
  o = o at(r0, c0) C_AC TL rep(H, w - 2) TR RST
  for (y = r0 + 1; y < r0 + h - 1; y++) o = o at(y, c0) C_AC V RST rep(" ", w - 2) C_AC V RST
  o = o at(r0 + h - 1, c0) C_AC BL rep(H, w - 2) BR RST
  o = o at(r0 + 1, c0 + 2) C_B pad(U["h.help"], w - 4) RST
  for (i = 1; i <= n; i++) {
    x = c0 + 2 + int((i - 1) / per) * colw; y = r0 + 2 + (i - 1) % per
    if (y >= r0 + h - 1) continue
    lab = k[i] == "help" ? U["h.cancel"] : U["h." k[i]]
    o = o at(y, x) C_AC pad(KEYT[i], kw) RST C_TX pad(lab, colw - kw - 1) RST
  }
}
# D: install the dotfiles? Says who for and what it writes; only y goes ahead.
function dotview(   w, h, r0, c0, n, i, r) {
  w = cols - 8; if (w > 64) w = 64
  n = wrap(fmt(U["dot.p"], du, "~/." df), w - 4)
  h = n + 6; if (h > rows - 2) h = rows - 2
  r0 = int((rows - h) / 2) + 1; if (r0 < 2) r0 = 2; c0 = int((cols - w) / 2) + 1
  o = o at(r0, c0) C_AC TL rep(H, w - 2) TR RST
  for (r = r0 + 1; r < r0 + h - 1; r++) o = o at(r, c0) C_AC V RST rep(" ", w - 2) C_AC V RST
  o = o at(r0 + h - 1, c0) C_AC BL rep(H, w - 2) BR RST
  o = o at(r0 + 1, c0 + 2) C_B pad(U["dot.title"], w - 4) RST
  r = r0 + 3
  for (i = 1; i <= n && r < r0 + h - 3; i++) { o = o at(r, c0 + 2) C_TX pad(WR[i], w - 4) RST; r++ }
  o = o at(r0 + h - 2, c0 + 2) C_AC pad(U["dot.keys"], w - 4) RST
}
function rot13(s,   i, c, p, o, lo, up) {
  lo = "abcdefghijklmnopqrstuvwxyz"; up = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"; o = ""
  for (i = 1; i <= length(s); i++) {
    c = substr(s, i, 1)
    if ((p = index(lo, c)) > 0) c = substr(lo, (p + 12) % 26 + 1, 1)
    else if ((p = index(up, c)) > 0) c = substr(up, (p + 12) % 26 + 1, 1)
    o = o c
  }
  return o
}
function put(r, c, w, style, text) { o = o at(r, c) style pad(text, w) RST }
# detail pane: one styled line, then the next row
function dl(style, text) { if (dr <= bot) { put(dr, dx - 1, dw + 2, style, " " text); dr++ } }
function dwrap(style, text,   n, i) { n = wrap(text, dw); for (i = 1; i <= n; i++) dl(style, WR[i]) }
function dbullet(text,   n, i) {
  n = wrap(text, dw - 2)
  for (i = 1; i <= n; i++) if (dr <= bot) {
    o = o at(dr, dx - 1) " " (i == 1 ? C_AC ARROW " " RST : "  ") C_TX pad(WR[i], dw - 1) RST; dr++
  }
}
function dfill() { while (dr <= bot) dl("", "") }
function stat(r, c, v, label,   shown) {
  shown = int(v * (tick + 1) / 8); if (shown > v) shown = v
  o = o at(r, c) C_B sprintf("%4d", shown) RST "  " C_DIM pad(label, 15) RST
}
function volbar(   v) {
  v = vol + 0; if (v < 0) v = 0; if (v > 10) v = 10
  return U["h.vol"] " " rep(VON, v) rep(VOFF, 10 - v)
}
function hex2(s) { return (index(HEXD, substr(s, 1, 1)) - 1) * 16 + index(HEXD, substr(s, 2, 1)) - 1 }
# brightness (0..1) of an xterm-256 colour, for terminals without colour
function lum(i,   r, g, b) {
  if (i >= 232) return (i - 232) / 23
  if (i < 16) return i / 15
  i -= 16; r = int(i / 36); g = int(i % 36 / 6); b = i % 6
  return (r * 3 + g * 6 + b) / 50
}
# A photograph in half-block cells: each character is two pixels, one in the foreground colour
# (top) and one in the background colour (bottom). Scaled to fit, centred, aspect kept.
function art(r0, c0, maxw, maxh, id, n,   w, h, px, sc, tw, th, x, y, sx, t, b, ct, cb, line, ramp, off) {
  w = IW[id, n]; h = IH[id, n]; px = IP[id, n]
  if (w < 1 || maxw < 8 || maxh < 3) return 0
  sc = maxw / w; if (2 * maxh / h < sc) sc = 2 * maxh / h
  tw = int(w * sc); th = int(h * sc / 2); if (tw < 1 || th < 1) return 0
  off = int((maxw - tw) / 2)
  ramp = " .:-=+*#%@"
  for (y = 0; y < th; y++) {
    line = at(r0 + y, c0 + off); ct = cb = -1
    for (x = 0; x < tw; x++) {
      sx = int(x * w / tw)
      if (IE[id, n]) {                         # a small search picture: a character a pixel
        t = CHX[substr(px, int(2 * y * h / (2 * th)) * w + sx + 1, 1)]
        b = CHX[substr(px, int((2 * y + 1) * h / (2 * th)) * w + sx + 1, 1)]
      } else {
        t = hex2(substr(px, (int(2 * y * h / (2 * th)) * w + sx) * 2 + 1, 2))
        b = hex2(substr(px, (int((2 * y + 1) * h / (2 * th)) * w + sx) * 2 + 1, 2))
      }
      if (color && utf) {
        if (t != ct) { line = line ESC "[38;5;" t "m"; ct = t }
        if (b != cb) { line = line ESC "[48;5;" b "m"; cb = b }
        line = line "▀"
      } else line = line substr(ramp, int((lum(t) + lum(b)) / 2 * 9.99) + 1, 1)
    }
    o = o line RST
  }
  return th
}
function addhit(t, s, label, kind) { nmh++; MT[nmh] = t; MS[nmh] = s; MLB[nmh] = label; MKD[nmh] = kind }
# Everything that mentions the query: names first, then anything whose text contains it.
function find(   i, lq, pass, inname, inbody, sk) {
  nmh = 0; lq = tolower(q); if (lq == "") return
  for (i = 1; i <= nk; i++) sk = sk " " KS[i]
  for (pass = 1; pass <= 2; pass++) {
    for (i = 1; i <= np; i++) {
      if (PGH[i]) continue
      inname = index(tolower(PT[i]), lq) > 0; inbody = index(tolower(PG[i] " " PS[i] " " PX[i] " " PL[i]), lq) > 0
      if ((pass == 1 && inname) || (pass == 2 && !inname && inbody)) addhit(2, i - 1, PT[i], U["k.project"])
    }
    for (i = 1; i <= nj; i++) {
      inname = index(tolower(JC[i] " " JR[i]), lq) > 0; inbody = index(tolower(JF[i] " " JP[i] " " JB[i]), lq) > 0
      if ((pass == 1 && inname) || (pass == 2 && !inname && inbody)) addhit(3, i - 1, JC[i], U["k.work"])
    }
    if (pass == 2 && index(tolower(sk), lq) > 0) addhit(3, 0, U["skills"], U["k.work"])
    for (i = 1; i <= nh; i++) {
      inname = index(tolower(HL[i]), lq) > 0; inbody = index(tolower(HX[i]), lq) > 0
      if ((pass == 1 && inname) || (pass == 2 && !inname && inbody)) addhit(4, i - 1, HL[i], U["k.photos"])
    }
    for (i = 1; i <= nc; i++) if (pass == 1 && index(tolower(CL[i] " " CV[i]), lq) > 0) addhit(5, i - 1, CL[i], U["k.contact"])
    if (pass == 2) for (i = 1; i <= nf && nmh < 80; i++) if (index(tolower(FT[i]), lq) > 0) addhit(9, i, FT[i], U["k.photo"])
  }
}
function section() {
  if (tab == 2) projects(); else if (tab == 3) experience(); else if (tab == 4) photos(); else if (tab == 5) contact()
}
function searchview(   i, r, label, r0, a, hgt) {
  if (nmh > 0) {
    if (ssel >= nmh) ssel = nmh - 1
    tab = MT[ssel + 1]; sel = MS[ssel + 1]
    if (tab == 9) {                           # one photograph: say what it is, enter opens it
      tab = 4; chrome(); dr = top
      dl(C_B, U["photo"]); dl("", ""); dwrap(C_TX, FT[sel]); dl("", "")
      dl(C_DIM, U["galleryopen"]); dl(C_AC, FU[sel]); dl("", "")
      r0 = dr; dfill()
      # its half-block art, when the script carries it (the photographs shown on the Photography tab)
      if (split(FA[sel], a, " ") == 2) hgt = art(r0, dx, dw, bot - r0 + 1, a[1], a[2] + 0)
      else if (ni["m" FO[sel]]) hgt = art(r0, dx, dw < 54 ? dw : 54, bot - r0 + 1, "m" FO[sel], 1)
    } else if (tab == 5) {
      chrome(); dr = top
      dl(C_B, CL[sel + 1]); dl("", ""); dl(C_TX, CK[sel + 1] == "email" ? rot13(CV[sel + 1]) : CV[sel + 1]); dfill()
    } else { chrome(); section() }            # the match itself, in its own section's detail pane
    sel = ssel; list_begin(nmh)
    for (i = 1; i <= nmh; i++) list_row(i, MLB[i], MKD[i])
    list_end(nmh)
  } else {
    tab = 2; chrome()
    for (r = top; r <= bot; r++) o = o at(r, 2) rep(" ", LW) at(r, split_col + 1) rep(" ", cols - split_col - 1)
    put(top + 1, 4, LW - 4, C_DIM, q == "" ? U["typesearch"] : U["nomatch"])
    put(top + 1, dx, dw, C_DIM, U["scope"])
  }
  label = nmh == 1 ? U["match1"] : fmt(U["matchn"], nmh)
  o = o at(2, 2) C_AC " / " RST C_B pad(q "_", 34) RST C_DIM pad(q == "" ? "" : label, cols - 41) RST
}

function url_for(   i) {
  if (tab == 2) return PU[sel + 1]
  if (tab == 3) return S["resume"]
  if (tab == 4) return HU[sel + 1]
  if (tab == 5) { i = sel + 1; return CK[i] == "email" ? "mailto:" rot13(CV[i]) : CU[i] }
  return S["origin"]
}

BEGIN { FS = "\t"; ESC = "\033"; HEXD = "0123456789abcdef"; uinit() }
# Records before the first L line are English (and plain ASCII). An "L xx" block holds language
# xx: only the records and strings that differ, which replace the English ones by index.
$1 == "L" { skip = ($2 != lang); next }
skip { next }
$1 == "S" { S[$2] = $3; next }
$1 == "T" { if ($3 != "") U[$2] = $3; next }
$1 == "N" { i = $2 + 0; if (i > nn) nn = i; NL[i] = $3; NV[i] = $4; next }
$1 == "G" { GT = $2; GW = $3; nw = int(length(GW) / 7); next }
$1 == "I" { ni[$2]++; IW[$2, ni[$2]] = $3; IH[$2, ni[$2]] = $4; IP[$2, ni[$2]] = $5; IC[$2, ni[$2]] = $6; ID[$2, ni[$2]] = $7; next }
$1 == "i" { IC[$2, $3 + 0] = $4; next }
$1 == "Y" { ny++; YY[ny] = $2; YN[ny] = $3; if ($3 > ymax) ymax = $3; next }
$1 == "P" { i = $2 + 0; if (i > np) np = i; PT[i] = $3; PD[i] = $4; PG[i] = $5; PU[i] = $6; PS[i] = $7; PX[i] = $8; PL[i] = $9; next }
$1 == "J" { i = $2 + 0; if (i > nj) nj = i; JR[i] = $3; JC[i] = $4; JW[i] = $5; JP[i] = $6; JF[i] = $7; JB[i] = $8; next }
$1 == "K" { i = $2 + 0; if (i > nk) nk = i; KY[i] = $3; KS[i] = $4; KM[i] = $5; next }
$1 == "E" { i = $2 + 0; if (i > ne) ne = i; ET[i] = $3; ES[i] = $4; EB[i] = $5; next }
$1 == "H" { i = $2 + 0; if (i > nh) nh = i; HL[i] = $3; HN[i] = $4; HU[i] = $5; HX[i] = $6; next }
$1 == "F" { i = $2 + 0; if (i > nf) nf = i; FT[i] = $3; FU[i] = $4; FD[i] = $5; FA[i] = $6; next }
$1 == "M" { k = "m" $2; ni[k] = 1; IW[k, 1] = $3; IH[k, 1] = $4; IP[k, 1] = $5; IE[k, 1] = 1; next }
$1 == "W" { WT[$2] = $3; WL[$2] = $4; if (wfirst == "" || $2 < wfirst) wfirst = $2; next }
$1 == "Q" { nq++; QD[nq] = $2; QL[nq] = $3 + 0; QS[nq] = $4 + 0; next }
$1 == "Z" { nz++; ZI[$2] = nz; ZID[nz] = $2; ZFROM[nz] = $3; ZTO[nz] = $4; ZDAY[nz] = $5; ZRULE[nz] = $6; ZB[nz] = $7 + 0; ZA[nz] = $8 + 0; ZDATE[nz] = $9; ZEF[nz] = $10; ZGR[nz] = $11 + 0; ZLT[nz] = $12 + 0; next }
$1 == "C" { i = $2 + 0; if (i > nc) nc = i; CL[i] = $3; CV[i] = $4; CU[i] = $5; CK[i] = $6; next }

END {
  if (want == "bye") { print S["bye"]; exit }
  if (want == "card") { timemachine(); seasons(); theme(); card(); exit }
  timemachine()
  if (want == "counts") { print np, nj, nh, nc; exit }
  if (want == "pick") { pickitems(); print (td != "" ? (isdate(td) ? td : "!") : PKI[psel + 1] == "now" ? "-" : PKI[psel + 1]); exit }
  if (q != "") find()
  if (want == "count") { print nmh + 0; exit }
  if (want == "hit") { if (sel + 1 <= nmh) print MT[sel + 1], (MT[sel + 1] == 9 ? FU[MS[sel + 1]] : MS[sel + 1]); exit }
  if (want == "resume") { resume_md(); exit }
  if (want == "url") { print url_for(); exit }
  if (want == "plain") { plain(); exit }
  seasons(); theme(); o = ""
  if (warp) { warpview(); exit }
  if (cols < 64 || rows < 16) {
    o = ESC "[2J"; n = wrap(U["small"], cols - 2)
    for (i = 1; i <= n; i++) o = o at(int(rows / 2) - 1 + i, 2) WR[i]
    printf "%s", o; exit
  }
  LW = cols >= 100 ? 36 : 30                  # list pane width
  split_col = LW + 2; top = 4; bot = rows - 2 - HROWS; PH = bot - top + 1
  dx = LW + 4; dw = cols - LW - 5             # detail pane text origin and width
  wide = (mode != 1 && (tab == 1 || tab == 5))
  if (mode == 1) searchview()
  else { chrome(); if (tab == 1) overview(); else section() }
  if (mode == 2) picker()
  if (mode == 3) dotview()
  if (mode == 0 && lg == "help") helpview()
  # what Tom is playing (and how loud), or why it is not playing
  if (music != "") {
    music = msg(music); if (playing) music = music "  " volbar()
    mw = dwidth(music)
    if (cols - mw - 5 <= HLEN + 2) { music = fit(music, cols - HLEN - 8); mw = TW }
    if (mw > 0) o = o at(rows - 1, cols - mw - 4) C_TE (playing ? NOTE : " ") " " music RST
  }
  printf "%s", o
}

function theme(   i) {
  RST = ESC "[0m"
  if (color) {
    C_FR = ESC "[38;5;60m"; C_AC = ESC "[38;5;75m"; C_TE = ESC "[38;5;79m"; C_DIM = ESC "[38;5;245m"
    C_TX = ESC "[38;5;252m"; C_B = ESC "[1m" ESC "[38;5;255m"; C_SEL = ESC "[48;5;25m" ESC "[38;5;231m" ESC "[1m"
  } else { C_FR = C_AC = C_TE = C_DIM = C_TX = ""; C_B = ESC "[1m"; C_SEL = ESC "[7m" }
  if (SZ && color) C_AC = ESC "[38;5;" ACC "m"   # the season's accent
  NG = split(utf ? "▚ ▞ ▙ ▟ ▛ ▜ ░ ▒ ▓ █ ▄ ▀ ╱ ╲ ┼ ╳" : "# % @ & = + / \\ < > _ ~", GL, " ")
  C_GH = color ? ESC "[38;5;141m" : ""
  if (utf) {
    H = "─"; V = "│"; TL = "╭"; TR = "╮"; BL = "╰"; BR = "╯"; LT = "├"; RT = "┤"; TT = "┬"; BT = "┴"
    BLK = "█"; SHD = "░"; ARROW = "▸"; STAR = "✦"; SCAN = "━"; DOT = "·"
    BAR[1] = "▁"; BAR[2] = "▂"; BAR[3] = "▃"; BAR[4] = "▄"; BAR[5] = "▅"; BAR[6] = "▆"; BAR[7] = "▇"; BAR[8] = "█"
    NOTE = "♪"; VON = "█"; VOFF = "░"
    HK["move"] = "↑↓"; HK["section"] = "←→"
  } else {
    H = "-"; V = "|"; TL = TR = BL = BR = LT = RT = TT = BT = "+"
    BLK = "#"; SHD = "."; ARROW = ">"; STAR = "*"; SCAN = "="; DOT = "-"
    for (i = 1; i <= 8; i++) BAR[i] = i < 5 ? "." : "#"
    NOTE = "~"; VON = "#"; VOFF = "."
    HK["move"] = "^v"; HK["section"] = "<>"
  }
  HK["search"] = "/"; HK["music"] = HK["musicoff"] = "m"; HK["save"] = HK["resume"] = "r"; HK["lang"] = "L"
  HK["open"] = HK["jump"] = "enter"; HK["quit"] = "q"; HK["type"] = ""; HK["cancel"] = "esc"; HK["vol"] = "- +"
  HK["tm"] = "t"; HK["now"] = "T"; HK["fx"] = "s"; HK["dot"] = "D"; HK["date"] = "0-9"; HK["go"] = "enter"; U["h.go"] = U["tm.go"]
  # The key legend: every control, with what it does in words. One line when it fits (with the
  # shorter "resume" label if need be), otherwise as many lines as it takes (up to three); the
  # last line leaves room on its right for the song title or a notice.
  reserve = 0
  if (music != "") reserve = dwidth(msg(music)) + (playing ? dwidth(volbar()) + 2 : 0) + 6
  if (mode == 1) { gap = "   "; hl = "type move jump cancel" }
  else if (mode == 2) { gap = "   "; hl = "date move go cancel" }
  else if (mode == 3) { gap = "   "; hl = "cancel" }
  else { gap = "  "; hl = "move section search " (playing ? "musicoff" : "music") " vol save tm" (travel ? " now" : "") " fx lang dot open quit" }
  HELP = legend(hl, gap); HROWS = 1
  if (dwidth(HELP) > cols - 2 - reserve && mode == 0) { sub(/save/, "resume", hl); HELP = legend(hl, gap) }
  HLN[1] = HELP; HLN[2] = HLN[3] = ""
  if (dwidth(HELP) > cols - 2 - reserve) {
    nh_ = split(hl, HC, " "); HROWS = 1; HLN[1] = ""
    for (i = 1; i <= nh_; i++) {
      t_ = substr(legend(HC[i], gap), 2)
      if (HLN[HROWS] != "" && dwidth(HLN[HROWS]) + length(gap) + dwidth(t_) > cols - 3 && HROWS < 3) HROWS++
      HLN[HROWS] = HLN[HROWS] (HLN[HROWS] == "" ? "" : gap) t_
    }
    for (i = 1; i <= HROWS; i++) HLN[i] = " " HLN[i]
  }
  # After the first moments the legend condenses to one row of keys, with "h help" always there;
  # h (or ?) shows every control with its words, over the screen.
  if (mode == 0 && lg != "full") {
    HROWS = 1; t_ = ""
    split("move section search music vol resume tm" (travel ? " now" : "") " fx lang dot open quit", HC, " ")
    for (i = 1; HC[i] != ""; i++) t_ = t_ " " (HC[i] == "open" ? (utf ? "⏎" : "enter") : HC[i] == "vol" ? "-+" : HK[HC[i]])
    HLN[1] = t_ "   " C_B "h" RST C_DIM " " U["h.help"]
    HLW[1] = dwidth(t_) + 5 + dwidth(U["h.help"])
    HLEN = HLW[1]
  } else {
    for (i = 1; i <= HROWS; i++) { HLN[i] = fit(HLN[i], cols - 2); HLW[i] = TW }
    HLEN = HLW[HROWS]                         # the line the music notice shares
  }
  if (color) { GC[0] = ESC "[38;5;237m"; GC[1] = ESC "[38;5;24m"; GC[2] = ESC "[38;5;31m"; GC[3] = ESC "[38;5;38m"; GC[4] = ESC "[38;5;51m" }
  else GC[0] = GC[1] = GC[2] = GC[3] = GC[4] = ""
  if (utf && color) for (i = 0; i <= 4; i++) GCH[i] = "■"
  else { GCH[0] = "."; GCH[1] = ":"; GCH[2] = "+"; GCH[3] = "*"; GCH[4] = "#" }
}

function chrome(   title, right, i, n, names, plen, r, mid, site, p, w) {
  # the clock, or the time machine's destination day
  title = " " S["name_upper"] " "; right = " " S["langname"] "  " (travel ? (utf ? "◷ " : "@ ") D : clock) " "
  if (dwidth(title) + dwidth(right) > cols - 4) right = " " (travel ? D : clock) " "
  o = o at(1, 1) C_FR TL H RST C_B title RST C_FR rep(H, cols - 4 - dwidth(title) - dwidth(right)) RST (travel ? C_TE : C_AC) right RST C_FR H TR RST
  # the season in the header: a greeting on the day, a little weather either side
  if (SZ) {
    p = 2 + dwidth(title) + 2; w = cols - 2 - dwidth(right) - 2   # the free stretch of the top line
    if (GREET != "" && dwidth(GREET) + 6 <= w - p) {
      r = int((p + w - dwidth(GREET)) / 2)
      o = o at(1, r - 2) C_AC STAR " " C_B GREET RST C_AC " " STAR RST
      motif(1, p, 1, r - 4); motif(1, r + dwidth(GREET) + 3, 1, w)
    } else motif(1, p, 1, w)
  }
  # tabs, long names when they all fit
  w = 0
  for (i = 1; i <= 5; i++) { names[i] = U["t" i "^"]; w += dwidth(names[i]) + 5 }
  if (w > cols - 2) for (i = 1; i <= 5; i++) names[i] = U["s" i "^"]
  n = 5
  o = o at(2, 1) C_FR V RST; plen = 0
  for (i = 1; i <= n; i++) {
    w = dwidth(names[i])
    if (plen + w + 5 > cols - 2) break
    o = o " " (i == tab ? C_SEL " " i " " names[i] " " RST : C_AC " " i RST C_DIM " " names[i] " " RST)
    plen += w + 5
  }
  o = o rep(" ", cols - 2 - plen) C_FR V RST
  mid = wide ? H : TT
  o = o at(3, 1) C_FR LT rep(H, split_col - 2) mid rep(H, cols - split_col - 1) RT RST
  lights(3, 1, cols)
  for (r = top; r <= bot; r++) {
    o = o at(r, 1) C_FR V RST at(r, cols) C_FR V RST
    if (!wide) o = o at(r, split_col) C_FR V RST
  }
  mid = wide ? H : BT
  o = o at(rows - 1 - HROWS, 1) C_FR LT rep(H, split_col - 2) mid rep(H, cols - split_col - 1) RT RST
  for (i = 1; i <= HROWS; i++) o = o at(rows - 1 - HROWS + i, 1) C_FR V RST C_DIM HLN[i] rep(" ", cols - 2 - HLW[i]) RST C_FR V RST
  site = " " S["host"] " "
  o = o at(rows, 1) C_FR BL rep(H, cols - 3 - length(site)) RST C_DIM site RST C_FR H BR RST
  # a light that runs along the bottom edge
  p = 2 + (tick * 2) % (cols - 12 - length(site))
  o = o at(rows, p) C_AC rep(SCAN, 5) RST
}

function list_row(i, label, meta, ghost,   w, style, r) {
  r = top + i - ltop - 1
  if (r < top || r > bot) return
  meta = fit(meta, int(LW / 2)); w = LW - 2 - (meta == "" ? 0 : TW + 1)
  style = (i == sel + 1) ? C_SEL : ghost ? C_GH : C_TX
  o = o at(r, 2) style " " pad(label, w) (meta == "" ? "" : " " meta) " " RST
}
function list_begin(n,   r) {
  ltop = sel - int(PH / 2); if (ltop > n - PH) ltop = n - PH; if (ltop < 0) ltop = 0
  for (r = top; r <= bot; r++) o = o at(r, 2) rep(" ", LW)
  dr = top
}
function list_end(n,   pos) {
  if (n <= PH) return
  pos = int(ltop / (n - PH) * (PH - 1) + 0.5)
  o = o at(top + pos, split_col) C_AC BLK RST
}

function bigname(r, c,   F, L, text, row, i, j, ch, line, k, g, n, cur, col) {
  F["B"] = "#### |#   #|#### |#   #|#### "; F["L"] = "#    |#    |#    |#    |#####"
  F["A"] = " ### |#   #|#####|#   #|#   #"; F["I"] = "###| # | # | # |###"
  F["N"] = "#   #|##  #|# # #|#  ##|#   #"; F["E"] = "#####|#    |#### |#    |#####"
  F["M"] = "#   #|## ##|# # #|#   #|#   #"; F["R"] = "#### |#   #|#### |#  # |#   #"
  F["S"] = " ####|#    | ### |    #|#### "; F["O"] = " ### |#   #|#   #|#   #| ### "
  F["T"] = "#####|  #  |  #  |  #  |  #  "; F["D"] = "#### |#   #|#   #|#   #|#### "
  F["C"] = " ####|#    |#    |#    | ####"; F["H"] = "#   #|#   #|#####|#   #|#   #"
  F["G"] = " ####|#    |#  ##|#   #| ####"; F["K"] = "#   #|#  # |###  |#  # |#   #"
  F["P"] = "#### |#   #|#### |#    |#    "; F["U"] = "#   #|#   #|#   #|#   #| ### "
  F["V"] = "#   #|#   #|#   #| # # |  #  "; F["W"] = "#   #|#   #|# # #|## ##|#   #"
  F["Y"] = "#   #| # # |  #  |  #  |  #  "; F["F"] = "#####|#    |#### |#    |#    "
  n = split("27 33 39 45 44 43 49 43 44 45 39 33", g, " ")
  text = BIG != "" ? BIG : S["name_upper"]
  for (row = 1; row <= 5; row++) {
    line = ""
    for (i = 1; i <= length(text); i++) {
      ch = substr(text, i, 1)
      if (ch == " ") { line = line "   "; continue }
      if (!(ch in F)) continue
      split(F[ch], L, "|"); line = line L[row] " "
    }
    o = o at(r + row - 1, c); cur = -1
    for (j = 1; j <= length(line) && j <= cols - c - 1; j++) {
      if (substr(line, j, 1) == "#") {
        col = g[int((j + tick * 2) / 6) % n + 1]
        if (color && col != cur) { o = o ESC "[38;5;" col "m"; cur = col }
        o = o BLK
      } else o = o " "
    }
    o = o RST
  }
  return length(line)
}

function overview(   bw, lx, gl, lt, r, i, x0, xc, h, k, cell, n, big, hdr, eb, bars, need, gap, gw, lv, wk, d, ch, gx) {
  for (r = top; r <= bot; r++) o = o at(r, 2) rep(" ", cols - 2)
  x0 = 4; bars = 3
  big = (cols >= 76 && PH >= 18); hdr = (PH >= 21); eb = (PH >= 23)
  need = (big ? 5 : 1) + 1 + (eb ? 1 : 0) + (hdr ? 1 : 0) + bars + 1 + (nw ? 8 : 0)
  gap = int((PH - need) / 3); if (gap > 2) gap = 2; if (gap < 0) gap = 0
  r = top
  if (big) { bw = bigname(r, x0); motif(r, x0 + bw + 3, r + 4, cols - 3); r += 5 } else { put(r, x0, cols - 6, C_B, S["name"]); r++ }
  if (eb) { put(r, x0, cols - 6, C_DIM, S["eyebrow"]); r++ }
  put(r, x0, cols - 6, C_B, S["tagline"]); r++
  r += gap

  # the numbers, and how many projects each year
  xc = x0 + 46
  if (hdr) {
    put(r, x0, 40, C_AC, U["numbers^"])
    if (cols >= xc + ny * 2) put(r, xc, cols - xc - 1, C_AC, U["byyear^"])
    r++
  }
  for (i = 1; i <= nn; i++) stat(r + int((i - 1) / 2), x0 + ((i - 1) % 2) * 22, NV[i], NL[i])
  if (cols >= xc + ny * 2) {
    for (i = 1; i <= ny; i++) {
      h = int(YN[i] / ymax * bars * 8 + 0.5); if (YN[i] > 0 && h < 1) h = 1; if (h > tick * 3) h = tick * 3
      for (k = 1; k <= bars; k++) {
        cell = h >= k * 8 ? BAR[8] : (h > (k - 1) * 8 ? BAR[h - (k - 1) * 8] : " ")
        o = o at(r + bars - k, xc + (i - 1) * 2) (i == ny ? C_TE : C_AC) cell RST
      }
      if (i % 2 == ny % 2) o = o at(r + bars, xc + (i - 1) * 2) C_DIM substr(YY[i], 3, 2) RST
    }
  }
  r += bars + 1 + gap

  if (GHM == "none" && r + 1 <= bot) { o = o at(r, x0) C_AC "GITHUB" RST C_DIM "  " fit(U["gh.none"], cols - x0 - 12) RST; r += 2 + gap }
  # a year of GitHub, one column per week
  if (nw && r + 7 <= bot) {
    gw = (cols >= x0 + nw * 2 + 4) ? 2 : 1
    gx = x0
    gl = GHM == "past" ? (GT == "" ? U["gh.none"] : fmt(U["contrib.y"], GT, DY)) : GHM == "future" ? U["fut.unwritten"] : fmt(U["contrib"], GT)
    o = o at(r, x0) C_AC "GITHUB" RST C_DIM "  " gl RST
    gx = x0 + 8 + dwidth(gl) + 3
    if (gx + dwidth(U["less"]) + dwidth(U["more"]) + 7 < cols) {
      o = o at(r, gx) C_DIM U["less"] " " RST
      for (lv = 0; lv <= 4; lv++) o = o GC[lv] GCH[lv] RST
      o = o C_DIM " " U["more"] RST
    }
    gx = x0
    for (d = 0; d < 7; d++) {
      o = o at(r + 1 + d, gx)
      for (wk = 0; wk < nw; wk++) {
        ch = substr(GW, wk * 7 + d + 1, 1)
        if (GHM == "future") { o = o C_GH GL[(wk * 7 + d * 3 + int(tick / 3)) % NG + 1] RST (gw == 2 ? " " : ""); continue }
        if (ch == "." || wk > tick * 5) { o = o rep(" ", gw); continue }
        o = o GC[ch + 0] GCH[ch + 0] RST (gw == 2 ? " " : "")
      }
    }
    r += 8 + gap
  }
  lx = ""; k = 0
  for (i = 1; i <= np && k < 3; i++) if (!PGH[i]) { lx = lx (k ? "  " DOT "  " : "") PT[i]; k++ }
  if (r <= bot) { lt = U["latest^"] "  "; o = o at(r, x0) C_AC lt RST C_TX fit(lx, cols - 6 - dwidth(lt)) RST; r += 2 }
  n = wrap(S["lede"], cols - 8)
  for (i = 1; i <= n && r <= bot; i++) { put(r, x0, cols - 6, C_DIM, WR[i]); r++ }
}

# Text that flows around something pinned to the top-right of the detail pane (an icon): lines
# beside it are narrower, lines below it use the full width.
function dflow(style, text,   k, i, line, lw, s, w) {
  k = tok(text); line = ""; lw = 0
  for (i = 1; i <= k; i++) {
    w = (dr < flowbot) ? flownarrow : flowfull
    s = line == "" ? 0 : TKS[i]
    if (line != "" && lw + s + TKW[i] > w) { dw = w; dl(style, line); line = ""; lw = 0; s = 0 }
    line = line (s ? " " : "") TK[i]; lw += s + TKW[i]
  }
  if (line != "") { dw = (dr < flowbot) ? flownarrow : flowfull; dl(style, line) }
  dw = flowfull
}
function dblank() { dw = (dr < flowbot) ? flownarrow : flowfull; dl("", ""); dw = flowfull }
function projects(   i, n, k, chips, c, iw, ih, key, icon, r0) {
  list_begin(np)
  for (i = 1; i <= np; i++) {
    if (PGH[i] == 1) list_row(i, scr(PTL[i], i), PD[i], 1)   # work still to come: unreadable
    else list_row(i, PT[i], PD[i], PGH[i])
  }
  list_end(np)
  i = sel + 1; key = "p" PO[i]; flowfull = dw
  if (PGH[i]) {                               # from after your time
    if (PGH[i] == 1) { dl(C_GH, scr(PTL[i], i)); dl(C_DIM, PD[i]); dl("", ""); dwrap(C_B, U["fut.unwritten"]) }
    else { dwrap(C_B, U["fut.unwritten"]); if (PD[i] != "") dl(C_DIM, PD[i]) }
    dl("", ""); dwrap(C_DIM, U["fut.unwritten.p"]); dl("", "")
    r0 = dr; dfill()
    if (PGH[i] == 1) glitch(r0, dx, dw < 40 ? dw : 40, bot - r0 + 1 < 10 ? bot - r0 + 1 : 10, i)
    return
  }
  iw = (PH >= 24 && dw >= 60) ? 24 : 14; ih = iw / 2
  icon = (ni[key] > 0 && dw >= 40)
  flownarrow = icon ? flowfull - iw - 2 : flowfull
  flowbot = icon ? top + ih + 1 : top
  dflow(C_B, PT[i])
  if (PG[i] != "") dflow(C_TE, PG[i])
  dflow(C_DIM, PL[i])
  dblank()
  dflow(C_TX, PX[i])
  dblank()
  n = split(PS[i], c, ", "); chips = ""
  for (k = 1; k <= n; k++) chips = chips "[" c[k] "] "
  dflow(C_AC, chips)
  dblank()
  if (PU[i] != "") { dflow(C_DIM, U["enteropens"]); dflow(C_AC, PU[i]) }
  while (dr <= bot) dblank()
  if (icon) {
    for (k = top; k < flowbot; k++) o = o at(k, dx + flownarrow + 1) rep(" ", iw + 2)
    art(top, dx + flownarrow + 2, iw, ih, key, 1)
  }
}
function lput(r, style, text) { if (r <= bot) put(r, 3, LW - 2, style, text) }
function experience(   i, n, k, b, f, w, r, m, need, realbot) {
  list_begin(nj)
  for (i = 1; i <= nj; i++) list_row(i, JC[i], substr(JW[i], 4, 4))
  # the rest of the side pane: how long each group of skills goes back, then education
  r = top + nj + 1
  lput(r, C_AC, U["skills^"]); r++
  w = LW - 2 - 14
  for (k = 1; k <= nk && r <= bot; k++) {
    f = int(KM[k] / 100 * w + 0.5); if (f > tick * 3) f = tick * 3
    o = o at(r, 3) C_DIM pad(KY[k], 14) RST C_AC rep(BLK, f) C_FR rep(SHD, w - f) RST; r++
  }
  r++
  lput(r, C_AC, U["education^"]); r++
  for (k = 1; k <= ne; k++) {
    m = wrap(ET[k], LW - 2); for (i = 1; i <= m; i++) { lput(r, C_TX, WR[i]); r++ }
    m = wrap(ES[k], LW - 2); for (i = 1; i <= m; i++) { lput(r, C_DIM, WR[i]); r++ }
  }
  lput(bot, C_DIM, U["fullresume"])

  # The skills panel is pinned to the bottom of the detail pane, the same rows for every job,
  # as tall as it needs but always leaving the job at least nine rows.
  need = 1
  for (k = 1; k <= nk; k++) need += wrap(KY[k] ": " KS[k], dw)
  if (need > PH - 10) need = PH - 10
  realbot = bot
  if (need >= 3) bot = realbot - need - 1
  i = sel + 1
  dwrap(C_B, JR[i]); dwrap(C_TE, JC[i]); dwrap(C_DIM, JW[i] "  " DOT "  " JP[i]); dwrap(C_DIM, JF[i]); dl("", "")
  n = split(JB[i], b, "|")
  for (k = 1; k <= n; k++) dbullet(b[k])
  dfill()
  if (need >= 3) {
    o = o at(bot + 1, dx - 1) C_FR rep(H, dw + 2) RST
    bot = realbot; dr = bot - need + 1
    dl(C_AC, U["skills^"])
    for (k = 1; k <= nk && dr <= bot; k++) dwrap(C_TX, KY[k] ": " KS[k])
    dfill()
  }
}
function photos(   i, r0, n, which, hgt, k, g) {
  list_begin(nh)
  for (i = 1; i <= nh; i++) list_row(i, HL[i], HN[i])
  list_end(nh)
  i = sel + 1
  dwrap(C_B, HL[i] (HN[i] == "" ? "" : "  (" HN[i] ")"))
  dwrap(C_DIM, HX[i])
  dl(C_AC, HU[i])
  dl("", "")
  if (i == 3 && ngo) {                        # the dogs who have gone, remembered
    dwrap(C_B, U["fut.museum.h"]); dwrap(C_DIM, U["fut.museum.p"])
    for (k = ngo; k >= 1 && k > ngo - 24 && dr <= bot; k--) { g = GO[k]; dl(C_TX, DGN[g] "  " substr(dstr(DGB[g]), 1, 4) " - " substr(dstr(DGE[g]), 1, 4)) }
    dl("", "")
  }
  r0 = dr; dfill()
  if (i == 3 && ghostdogs) {                  # nobody has photographed these dogs yet
    if (bot - r0 + 1 >= 4) glitch(r0, dx, dw < 48 ? dw : 48, bot - r0 + 1 < 14 ? bot - r0 + 1 : 14, 3 + DY)
    return
  }
  n = ni[i]
  if (n < 1) return
  which = int(tick / 40) % n + 1               # every eight seconds, the next photograph
  hgt = art(r0, dx, dw, bot - r0 - 1, i, which)
  if (hgt > 0 && r0 + hgt <= bot) put(r0 + hgt, dx, dw, C_DIM, IC[i, which])
}

function contact(   i, r, gap, x0, lw, style, v, nl) {
  for (r = top; r <= bot; r++) o = o at(r, 2) rep(" ", cols - 2)
  x0 = 4; lw = 12
  nl = wrap(S["contact_note"], cols - 6); if (nl > 2) nl = 2
  for (i = 1; i <= nl; i++) put(top + i, x0, cols - 6, C_DIM, WR[i])
  gap = (PH >= nc * 2 + 4 + nl) ? 2 : 1
  for (i = 1; i <= nc; i++) {
    r = top + 2 + nl + (i - 1) * gap
    if (r > bot - 1) break
    v = CK[i] == "email" ? rot13(CV[i]) : CV[i]
    if (i == sel + 1) o = o at(r, x0 - 1) C_SEL " " ARROW " " pad(CL[i], lw) pad(v, cols - x0 - lw - 6) " " RST
    else o = o at(r, x0 - 1) "   " C_AC pad(CL[i], lw) RST C_TX pad(v, cols - x0 - lw - 6) RST " "
  }
  put(bot, x0, cols - 6, C_DIM, U["openselected"])
}

function resume_md(   i, n, k, b) {
  print "# " S["name"]; print ""; print S["title"] "  |  " S["origin"]; print ""
  print S["summary"]; print ""; print "## " U["t3"]
  for (i = 1; i <= nj; i++) {
    print ""; print "### " JR[i] ", " JC[i]; print JW[i] "  |  " JP[i] "  |  " JF[i]; print ""
    n = split(JB[i], b, "|"); for (k = 1; k <= n; k++) print "- " b[k]
  }
  print ""; print "## " U["skills"]; print ""
  for (k = 1; k <= nk; k++) print "- **" KY[k] ":** " KS[k]
  print ""; print "## " U["education"]; print ""
  for (k = 1; k <= ne; k++) print ET[k] "  " ES[k]
  print ""; print U["fullresumemd"] " " S["resume"]
}
function plain(   i, n) {
  print ""; print "  " S["name"] "  -  " S["eyebrow"]; print "  " S["origin"]; print ""
  n = wrap(S["tagline"], 72); for (i = 1; i <= n; i++) print "  " WR[i]
  print ""
  n = wrap(S["lede"], 72); for (i = 1; i <= n; i++) print "  " WR[i]
  print ""; for (i = 1; i <= nn; i++) print "  " sprintf("%5d", NV[i]) "  " NL[i]
  print ""; print "  " U["t2^"]
  for (i = 1; i <= np; i++) if (!PGH[i]) print "  " pad(PT[i], 28) " " PD[i] "  " PG[i]
  print ""; print "  " U["t3^"]
  for (i = 1; i <= nj; i++) print "  " JR[i] ", " JC[i] " (" JW[i] ")"
  print ""; print "  " U["t4^"]
  for (i = 1; i <= nh; i++) print "  " pad(HL[i], 18) " " HU[i]
  print ""; print "  " U["t5^"]
  for (i = 1; i <= nc; i++) print "  " pad(CL[i], 12) " " (CK[i] == "email" ? rot13(CV[i]) : CU[i])
  print ""
}
WM_AWK
)

# ---- language: WEMILLER_LANG, else the locale (LC_ALL, LC_MESSAGES, LANG), else English ----
UTF=0
case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in *UTF-8*|*utf8*|*UTF8*|*utf-8*) UTF=1 ;; esac
lang_of() {
  case "$1" in
    [Zz][Hh]*) echo zh-Hans ;; [Jj][Aa]*) echo ja ;; [Dd][Ee]*) echo de ;; [Ff][Rr]*) echo fr ;;
    [Ee][Ss]*) echo es ;; [Kk][Oo]*) echo ko ;; [Pp][Tt]*) echo pt-BR ;; [Ii][Tt]*) echo it ;;
    [Ee][Nn]*) echo en ;;
  esac
}
LANGC=$(lang_of "${WEMILLER_LANG:-}")
if [ -z "$LANGC" ]; then
  LANGC=$(lang_of "${LC_ALL:-${LC_MESSAGES:-${LANG:-}}}")
fi
[ -n "$LANGC" ] || LANGC=en
[ "$UTF" = 1 ] || LANGC=en                     # not a UTF-8 terminal: English, plain ASCII
next_lang() {
  case "$1" in
    en) echo zh-Hans ;; zh-Hans) echo ja ;; ja) echo de ;; de) echo fr ;; fr) echo es ;;
    es) echo ko ;; ko) echo pt-BR ;; pt-BR) echo it ;; *) echo en ;;
  esac
}
# The renderer. LC_ALL=C makes every awk count bytes; it decodes UTF-8 itself.
# The time machine (WEMILLER_WHEN=2090-01-01 or a named day such as christmas) and the seasons
# (WEMILLER_SEASONS=0 turns them off) are read by the renderer, against today's date.
WHEN=${WEMILLER_WHEN:-}
SEASONS=1; case "${WEMILLER_SEASONS:-1}" in 0|off|no|false) SEASONS=0 ;; esac
NOWD=$(date +%Y-%m-%d)
tui() { data | LC_ALL=C awk -v lang="$LANGC" -v today="$NOWD" -v when="$WHEN" -v fx="$SEASONS" "$@" "$PROG"; }

# ---- the radio behind m: songs composed in awk, written as WAV by sh ----
RADIO=$(cat <<'WM_RADIO'
# The radio: composes song n of station `seed` and writes it as raw mono PCM, SR samples a second,
# from sample `off` on, at volume `vol` (0-10, 10 when unset): 16-bit little-endian, or 8-bit with
# no zero byte when b8 is set (not every awk can print one). Its title goes to the file tf. The
# same seed and n always make the same song; cut keeps only its first few bars (for the tests).
function rnd(k) { return int(rand() * k) }
function pick(s,   a) { return a[rnd(split(s, a, " ")) + 1] }
function hz(m) { return HZ[m] }
# a sine from two parabolas, p in [0, 1): BusyBox awk can be built with no sin() at all
function sn(p) { return p < .5 ? 16 * p * (.5 - p) : 16 * (p - .5) * (p - 1) }
function nt(d) { return root + SC[d % 7 + 1] + 12 * int(d / 7) }
function tune(o, lo,   i, d) {                 # two bars of eighth notes, a step or two at a time
  d = lo + rnd(4)
  for (i = 0; i < 16; i++) {
    if (i % 4 && rnd(10) < 3) { MO[o, i] = -1; continue }
    d += rnd(5) - 2; if (d < lo) d = lo + 1; if (d > lo + 7) d = lo + 6
    MO[o, i] = d
  }
}
BEGIN {
  # no exp(), log() or sin() anywhere: BusyBox awk can be built without them. Pitches come from a table.
  HZ[69] = 440 / SR; for (m = 70; m < 128; m++) HZ[m] = HZ[m - 1] * 1.0594630943592953
  for (m = 68; m >= 0; m--) HZ[m] = HZ[m + 1] / 1.0594630943592953
  srand(seed * 1000 + n)
  ST = rnd(3) + 1                              # 1 synthwave, 2 lo-fi, 3 rock
  if (ST == 1) {
    bpm = 92 + rnd(24); sw = 0; split("0 2 3 5 7 8 10", SC, " "); prog = pick("0,5,2,6 0,5,3,4 5,3,0,6 0,3,5,4")
    W1 = "Neon Chrome Midnight Sunset Laser Vapor Electric Velvet Cobalt Turbo"; W2 = "Drive Boulevard Skyline Arcade Horizon Run Grid Coast Nights Pulse"
    K = "1000100010001000"; H = "1111111111111111"; form = "00001111111122222222111111113333"; style = "synthwave"
  } else if (ST == 2) {
    bpm = 72 + rnd(14); sw = .2; split("0 2 4 5 7 9 11", SC, " "); prog = pick("1,4,0,5 3,2,1,0 0,5,1,4 3,4,2,5")
    W1 = "Rainy Sleepy Paper Late Window Quiet Amber Dusty Mellow Slow"; W2 = "Notes Tea Study Cafe Afternoon Pages Lanterns Steps Letters Haze"
    K = "1000000100100000"; H = "1010101010101010"; form = "0011111111222222221111"; style = "lo-fi"
  } else {
    bpm = 120 + rnd(30); sw = 0; split("0 2 3 5 7 8 10", SC, " "); prog = pick("0,5,6,0 0,3,5,6 0,6,5,6 5,6,0,0")
    W1 = "Iron Loud Wild Burning Highway Broken Steel Electric Last Restless"; W2 = "Engine Road Fire Heart Thunder Riders Signal Machine Weekend Static"
    K = "1000001010100000"; H = "1010101010101010"; form = "0011111111222222221111111133"; style = "rock"
  }
  root = 40 + rnd(8); split(prog, P, ","); tune(0, 7); tune(1, 9)
  printf "%s %s (%s)\n", pick(W1), pick(W2), style > tf; close(tf)
  if (cut) form = substr(form, 1, cut)
  bars = length(form); stp = SR * 60 / bpm / 4; total = 0
  for (s = 0; s < bars * 16; s++) total += int(stp * (s % 2 ? 1 - sw : 1 + sw))
  fade = total - int(stp * 16 * (ST == 2 ? 4 : 2)); t = 0
  G = 24000 * (vol == "" ? 1 : vol * vol / 100)
  cf1 = cf2 = cf3 = cf4 = bf = lf = af = 0; kp = sp = lp = hp = cp1 = cp2 = cp3 = cp4 = cq1 = cq2 = cq3 = 0
  KE = SE = HE = CE = 0; ce = be = le = ae = 0
  for (bar = 0; bar < bars; bar++) {
    sec = substr(form, bar + 1, 1) + 0; d = P[bar % 4 + 1] + 0
    for (s = 0; s < 16; s++) {
      len = int(stp * (s % 2 ? 1 - sw : 1 + sw))
      # drums: everything in the verses and bridge, only the kick under a synthwave intro
      if ((sec == 1 || sec == 2 || (sec == 0 && ST == 1)) && substr(K, s + 1, 1) == "1") { KE = 1; KF = 140 / SR }
      if ((sec == 1 || sec == 2) && (s == 4 || s == 12)) SE = ST == 2 ? .5 : 1
      if (sec < 3 && substr(H, s + 1, 1) == "1") HE = (s % 4 == 2 ? .5 : .3) * (ST == 1 && s % 2 ? .5 : 1)
      if (s == 0 && sec && bar % 8 == (ST == 2 ? 2 : 4) && sec < 3) CE = .6
      # chords: a held pad, soft sevenths twice a bar, or power chords on the eighths
      if (ST == 3 ? (sec == 2 ? s % 8 == 0 : s % 2 == 0) : ST == 2 ? (s == 0 || s == 6) : s == 0) {
        if (ST == 3) { m = nt(d) - 12; cf1 = hz(m); cf2 = hz(m + 7); cf3 = hz(m + 12); cf4 = 0; cpk = .3; cl = sec == 2 ? 8 * len : len * .8; cat = 30 }
        else { cf1 = hz(nt(d)); cf2 = hz(nt(d + 2)); cf3 = hz(nt(d + 4)); cf4 = ST == 2 ? hz(nt(d + 6)) : 0
               cpk = ST == 2 ? .2 : .16; cl = ST == 2 ? (s ? 10 : 6) * len : 16 * len; cat = ST == 2 ? 400 : 3000 }
        ca = 0
      }
      # bass
      if (ST == 2) { if (sec < 3 || s == 0) if (s == 0 || s == 7 || s == 10) { bf = hz(nt(d) - 12); ba = 0; bl = 3 * len; bpk = .5 } }
      else if (sec && s % 2 == 0 && (sec < 3 || s == 0)) { bf = hz(nt(d) - 12 + (ST == 1 && s % 4 == 2 ? 12 : 0)); ba = 0; bl = len * 1.6; bpk = ST == 3 ? .4 : .35 }
      # the tune: one in the verses, another in the bridge
      if ((sec == 1 || sec == 2) && s % 2 == 0) { md = MO[sec - 1, (bar % 2) * 8 + s / 2]; if (md >= 0) { lf = hz(nt(md)); la = 0; ll = 2 * len * (1 + rnd(2)); lpk = ST == 2 ? .25 : .2 } }
      # an arpeggio under synthwave
      if (ST == 1 && sec) { af = hz(nt(d + 2 * (s % 3)) + 12); aa = 0; al = len * .7 }
      for (i = 0; i < len; i++) {
        x = 0; tt = t++
        if (cf1) {
          if (ca < cl) ce = ca < cat ? ca * cpk / cat : cpk; else if ((ce *= .9992) < .0005) cf1 = 0
          ca++
          if ((cp1 += cf1) >= 1) cp1--; if ((cp2 += cf2) >= 1) cp2--; if ((cp3 += cf3) >= 1) cp3--
          if (ST == 1) {
            if ((cq1 += cf1 * 1.007) >= 1) cq1--; if ((cq2 += cf2 * 1.007) >= 1) cq2--; if ((cq3 += cf3 * 1.007) >= 1) cq3--
            x += (cp1 + cp2 + cp3 + cq1 + cq2 + cq3 - 3) * ce
          } else if (ST == 2) {
            if ((cp4 += cf4) >= 1) cp4--
            x += ((cp1 < .5 ? cp1 : 1 - cp1) + (cp2 < .5 ? cp2 : 1 - cp2) + (cp3 < .5 ? cp3 : 1 - cp3) + (cp4 < .5 ? cp4 : 1 - cp4) - 1) * 4 * ce
          } else { w = ((cp1 < .5) + (cp2 < .5) + (cp3 < .5)) * 6 - 9; w *= ce; x += w / (1 + (w < 0 ? -w : w)) * .35 }
        }
        if (bf) {
          if (ba < bl) be = ba < 40 ? ba * bpk / 40 : bpk; else if ((be *= .9992) < .0005) bf = 0
          ba++; if ((bp += bf) >= 1) bp--
          x += (ST == 2 ? sn(bp) : ST == 3 ? (bp < .5 ? .7 : -.7) : bp + bp - 1) * be
        }
        if (lf) {
          if (la < ll) le = la < 80 ? la * lpk / 80 : lpk; else if ((le *= .9992) < .0005) lf = 0
          la++; if ((lq += lf) >= 1) lq--
          x += (ST == 3 ? lq + lq - 1 : ST == 2 ? 4 * (lq < .5 ? lq : 1 - lq) - 1 : (lq < .5 ? .8 : -.8)) * le
        }
        if (af) {
          if (aa < al) ae = aa < 20 ? aa * .0035 : .07; else if ((ae *= .999) < .0005) af = 0
          aa++; if ((aq += af) >= 1) aq--
          x += aq < .25 ? 1.5 * ae : -.5 * ae
        }
        if (KE > .001) { if ((kp += KF) >= 1) kp--; KF = KF * .9993 + .0308 / SR; x += sn(kp) * KE * .9; KE *= .99975 }
        if (SE + HE + CE > .002) {
          r = rand() * 2 - 1; hh = r - hp; hp = r
          if (SE > .001) { if ((sp += 190 / SR) >= 1) sp--; x += (r * .35 + sn(sp) * .15) * SE; SE *= ST == 1 ? .99985 : .9996 }
          x += hh * (HE * .12 + CE * .1); HE *= .997; CE *= .99985
        }
        if (ST == 2) { if (rand() < .0003) x += rand() * .3 - .15; lp += (x - lp) * .35; x = lp }
        if (tt < 3000) x *= tt / 3000; else if (tt > fade) x *= (total - tt) / (total - fade)
        if (tt < off) continue
        y = int(x / (1 + (x < 0 ? -x : x) * .25) * G)
        if (y > 32767) y = 32767; else if (y < -32767) y = -32767
        if (b8) { y = int(y / 256) + 128; printf "%c", (y < 1 ? 1 : (y > 255 ? 255 : y)) }
        else { if (y < 0) y += 65536; printf "%c%c", y % 256, int(y / 256) }
      }
    }
  }
}
WM_RADIO
)
SR=22050
# Not every awk can print a zero byte (BusyBox cannot): there the sound is 8-bit, with none in it.
B8=1; [ $(LC_ALL=C awk 'BEGIN { printf "%c%c", 0, 65 }' | wc -c) = 2 ] && B8=0
# compose <station> <n> <title file> [volume] [from sample] [bars]: song n as raw PCM on stdout
compose() { LC_ALL=C awk -v SR="$SR" -v b8="$B8" -v seed="$1" -v n="$2" -v tf="$3" -v vol="${4:-}" -v off="${5:-0}" -v cut="${6:-0}" "$RADIO"; }
# wavhdr <bytes>: the 44-byte WAV header for that much of it
le() { wv=$1; wk=$2; while [ "$wk" -gt 0 ]; do printf "\\$(printf %03o $((wv % 256)))"; wv=$((wv / 256)); wk=$((wk - 1)); done; }
wavhdr() {
  wb=$((2 - B8))
  printf RIFF; le $(($1 + 36)) 4; printf 'WAVEfmt '; le 16 4; le 1 2; le 1 2
  le "$SR" 4; le $((SR * wb)) 4; le "$wb" 2; le $((8 * wb)) 2; printf data; le "$1" 4
}

TTY=/dev/tty
( : <"$TTY" ) 2>/dev/null || TTY=
if [ -z "$TTY" ] || [ ! -t 1 ]; then
  tui -v want=plain
  exit 0
fi

COLOR=1; [ -n "${NO_COLOR:-}" ] && COLOR=0
VOL=${WEMILLER_VOLUME:-7}
case "$VOL" in [0-9]|10) ;; *) VOL=7 ;; esac

# the query without its last character (which may be several bytes)
drop_last() {
  printf '%s' "$1" | LC_ALL=C awk 'BEGIN { for (i = 1; i < 256; i++) O[sprintf("%c", i)] = i }
    { s = s (NR > 1 ? "\n" : "") $0 }
    END { n = length(s); while (n > 0 && O[substr(s, n, 1)] >= 128 && O[substr(s, n, 1)] < 192) n--; if (n > 0) n--; printf "%s", substr(s, 1, n) }'
}

go() {
  if command -v open >/dev/null 2>&1; then open "$1"
  elif command -v xdg-open >/dev/null 2>&1; then xdg-open "$1" >/dev/null 2>&1 &
  elif command -v wslview >/dev/null 2>&1; then wslview "$1"
  fi
}

# ---- music: optional, off until you press m ----
MDIR=; MPID=; MSG=
music_off() {
  [ -n "$MPID" ] && kill "$MPID" 2>/dev/null
  MPID=
  if [ -n "$MDIR" ] && [ -d "$MDIR" ] && [ -f "$MDIR/radio" ]; then
    [ -s "$MDIR/pid" ] && kill "$(cat "$MDIR/pid")" 2>/dev/null      # the player: quiet at once
    rm -rf "$MDIR"                             # only ever the temporary folder this script made
  fi
  MDIR=
}
# gain <0-10>: the level as the players take it, 0.00 to 1.00 (a square, as ears hear it)
gain() { printf '%d.%02d' $(($1 * $1 / 100)) $(($1 * $1 % 100)); }
# play <wav> <0-10> <k>: in the background; the player's pid goes in "pid", "end.k" appears when it stops
play() {
  ( case $PLAYER in
      afplay) afplay -v "$(gain "$2")" "$1" & ;;
      pw-play) pw-play --volume="$(gain "$2")" "$1" & ;;
      paplay) paplay --volume=$((65536 * $2 * $2 / 100)) "$1" & ;;
      *) aplay -q "$1" & ;;                     # aplay has no volume: the song is written at the level
    esac
    echo $! >"$MDIR/pid"; wait $!; : >"$MDIR/end.$3" ) >/dev/null 2>&1 &
}
# The radio itself, in the background: compose a song, play it, compose the next while it plays.
# A new volume restarts the player where it was, so every player gets one, even with no volume flag.
radio() {
  trap - EXIT
  KID=
  trap 'kill $KID $(cat "$MDIR/pid" 2>/dev/null) 2>/dev/null; exit 0' TERM HUP
  station=$(( $(date +%s) % 100000 + $$ % 1000 )); k=0; n=0; cur=0
  TICK=1; sleep 0.01 2>/dev/null && TICK=0.25
  # mk <n> <slot> [from sample]: song n as slot.wav (aplay: at today's volume, which goes in slot.v)
  mk() {
    mv=; [ "$PLAYER" = aplay ] && mv=$(cat "$MDIR/vol")
    compose "$station" "$1" "$MDIR/$2.t" "$mv" "${3:-0}" >"$MDIR/$2.pcm" & KID=$!
    wait "$KID" && [ -s "$MDIR/$2.pcm" ] || { echo '%stoppedwhy|could not compose' >"$MDIR/now"; exit 1; }
    { wavhdr $(wc -c <"$MDIR/$2.pcm"); cat "$MDIR/$2.pcm"; } >"$MDIR/$2.wav"; rm -f "$MDIR/$2.pcm"
    echo "$mv" >"$MDIR/$2.v"
  }
  mk 0 s0
  while :; do
    nxt=$((1 - cur))
    [ "$PLAYER" = aplay ] && [ "$(cat "$MDIR/s$cur.v")" != "$(cat "$MDIR/vol")" ] && mk "$n" "s$cur"
    tr -d '\n' <"$MDIR/s$cur.t" >"$MDIR/now"
    vol=$(cat "$MDIR/vol"); k=$((k + 1)); play "$MDIR/s$cur.wav" "$vol" "$k"; t0=$(date +%s); at=0
    mk $((n + 1)) "s$nxt"                      # the next song, while this one plays
    while [ ! -e "$MDIR/end.$k" ]; do
      sleep "$TICK" & KID=$!; wait "$KID"
      v=$(cat "$MDIR/vol" 2>/dev/null) || exit 0
      [ "$v" = "$vol" ] && continue
      at=$((at + ($(date +%s) - t0) * SR)); vol=$v
      kill "$(cat "$MDIR/pid")" 2>/dev/null; while [ ! -e "$MDIR/end.$k" ]; do sleep "$TICK"; done
      if [ "$PLAYER" = aplay ]; then mk "$n" cue "$at"
      else
        skip=$((at * (2 - B8))); left=$(($(wc -c <"$MDIR/s$cur.wav") - 44 - skip))
        [ "$left" -gt 0 ] || break
        { wavhdr "$left"; tail -c +$((45 + skip)) "$MDIR/s$cur.wav"; } >"$MDIR/cue.wav"
      fi
      k=$((k + 1)); play "$MDIR/cue.wav" "$vol" "$k"; t0=$(date +%s)
    done
    rm -f "$MDIR"/end.*; n=$((n + 1)); cur=$nxt
  done
}
music_on() {
  PLAYER=
  for p in afplay pw-play paplay aplay; do     # the ones that come with the system
    if command -v "$p" >/dev/null 2>&1; then PLAYER=$p; break; fi
  done
  [ -n "$PLAYER" ] || { MSG='%noplayer'; return; }
  MDIR=$(mktemp -d 2>/dev/null) || { MDIR=; MSG='%notmp'; return; }
  : >"$MDIR/radio"; echo "$VOL" >"$MDIR/vol"; echo '%tuning' >"$MDIR/now"
  radio </dev/null >/dev/null 2>&1 &
  MPID=$!
  MSG=
}

# ---- dotfiles: D asks first; y installs them for whoever is running this ----
DUSER=$( (id -un 2>/dev/null || echo "${USER:-you}") | tr -cd 'A-Za-z0-9._-')
DFILE=zshlocal                                 # zsh and bash; BusyBox and other plain sh get ashlocal
command -v zsh >/dev/null 2>&1 || command -v bash >/dev/null 2>&1 || DFILE=ashlocal
dot_install() {
  MSG='%dotfail'
  [ -n "${HOME:-}" ] && [ -d "$HOME" ] || return
  dst="$HOME/.$DFILE"; tmp="$dst.new.$$"; src="${WM_ORIGIN:-@ORIGIN@}/dotfiles/$DFILE"
  if command -v curl >/dev/null 2>&1 && curl -fsSL --max-time 30 "$src" -o "$tmp" 2>/dev/null; then :
  elif command -v wget >/dev/null 2>&1 && wget -q -T 30 -O "$tmp" "$src" 2>/dev/null; then :
  else rm -f "$tmp"; return; fi
  # only ever put the real file in place: it names itself on its first line
  case "$(head -n 1 "$tmp" 2>/dev/null)" in "# ~/.$DFILE "*) ;; *) rm -f "$tmp"; return ;; esac
  mv -f "$tmp" "$dst" || { rm -f "$tmp"; return; }
  if [ "$DFILE" = zshlocal ]; then
    line='[ -f ~/.zshlocal ] && source ~/.zshlocal'
    set --
    { command -v zsh >/dev/null 2>&1 || [ -f "$HOME/.zshrc" ]; } && set -- "$@" "$HOME/.zshrc"
    { command -v bash >/dev/null 2>&1 || [ -f "$HOME/.bashrc" ]; } && set -- "$@" "$HOME/.bashrc"
  else
    line='[ -f ~/.ashlocal ] && . ~/.ashlocal'
    set -- "$HOME/.profile"
  fi
  for rc in "$@"; do                           # one line, once
    grep -qF "$line" "$rc" 2>/dev/null || printf '\n%s\n' "$line" >>"$rc" || return
  done
  MSG='%dotok'
}

N1=1; N2=@N_PROJECTS@; N3=@N_EXPERIENCE@; N4=@N_PHOTOS@; N5=@N_CONTACT@
# how many entries each section has on the destination day
recount() { set -- $(tui -v want=counts); N2=${1:-$N2}; N3=${2:-$N3}; N4=${3:-$N4}; N5=${4:-$N5}; s1=0; s2=0; s3=0; s4=0; s5=0; }
# The warp to another day: a dozen quick frames, any key skips them. Not on a dumb terminal.
warp() {
  case "${TERM:-}" in dumb|'') return ;; esac
  set -- "$1" $(stty size <"$TTY" 2>/dev/null)
  stty time 1 <"$TTY"
  k=1
  while [ "$k" -le 12 ]; do
    tui -v rows="${2:-24}" -v cols="${3:-80}" -v color="$COLOR" -v utf="$UTF" -v warp="$k" -v wfrom="$1" -v tick="$k"
    W=$(dd bs=1 count=1 2>/dev/null <"$TTY")
    [ -n "$W" ] && break
    k=$((k + 1))
  done
  stty time 2 <"$TTY"
  printf '\033[2J'
}
SAVED=$(stty -g <"$TTY")
DONE=0
cleanup() {
  [ "$DONE" = 1 ] && return
  DONE=1
  music_off
  stty "$SAVED" <"$TTY" 2>/dev/null
  printf '\033[0m\033[?25h\033[?1049l'
  # the verse from the home page on a card (WEMILLER_CARD=0 leaves it out)
  case "${WEMILLER_CARD:-1}" in 0|off|no|false) ;; *) tui -v want=card -v cols="${C:-80}" -v color="$COLOR" -v utf="$UTF"; echo ;; esac
}
trap cleanup EXIT
trap 'exit 0' INT TERM HUP

printf '\033[?1049h\033[?25l\033[2J'
stty -icanon -echo min 0 time 2 <"$TTY"       # a read gives up after 0.2 s: that is the frame clock

tab=1; s1=0; s2=0; s3=0; s4=0; s5=0; tick=0; LR=0; LC=0
mode=0; Q=; ssel=0; NM=0; psel=0; TD=
LEG=full; FR=0; KN=0                           # the legend: in full at first, then condensed
recount
[ -n "$WHEN" ] && warp ""
NL='
'
CR=$(printf '\r'); ESC=$(printf '\033'); TAB=$(printf '\t'); DEL=$(printf '\177'); BS=$(printf '\010')

while :; do
  set -- $(stty size <"$TTY" 2>/dev/null)
  R=${1:-24}; C=${2:-80}
  if [ "$R" != "$LR" ] || [ "$C" != "$LC" ]; then printf '\033[2J'; LR=$R; LC=$C; fi
  eval "sel=\$s$tab; n=\$N$tab"
  NOW=$MSG
  if [ -n "$MPID" ]; then
    if kill -0 "$MPID" 2>/dev/null; then NOW=$(tr -cd ' -~' <"$MDIR/now" 2>/dev/null | cut -c1-48)
    else NOW=$(tr -cd ' -~' <"$MDIR/now" 2>/dev/null | cut -c1-48); MSG=${NOW:-%stopped}; music_off; fi
  fi
  tui -v tab="$tab" -v sel="$sel" -v rows="$R" -v cols="$C" -v tick="$tick" \
    -v color="$COLOR" -v utf="$UTF" -v clock="$(date +%H:%M:%S)" \
    -v mode="$mode" -v q="$Q" -v ssel="$ssel" -v music="$NOW" -v playing="${MPID:+1}" -v vol="$VOL" \
    -v psel="$psel" -v td="$TD" -v lg="$LEG" -v du="$DUSER" -v df="$DFILE"
  K=$(dd bs=1 count=1 2>/dev/null <"$TTY"; printf x); K=${K%x}
  tick=$((tick + 1)); FR=$((FR + 1))
  # the full legend reads for a few seconds or a few keys, then condenses (h brings it back)
  if [ "$LEG" = full ]; then [ -n "$K" ] && KN=$((KN + 1)); { [ "$FR" -ge 30 ] || [ "$KN" -ge 4 ]; } && LEG=short; fi
  [ -z "$K" ] && continue
  if [ "$mode" = 3 ]; then                    # ---- install the dotfiles? only y does ----
    [ "$K" = "$ESC" ] && K=$(dd bs=1 count=2 2>/dev/null <"$TTY"; printf x)   # the rest of an arrow key
    case "$K" in y|Y) dot_install ;; *) MSG='%dotno' ;; esac
    mode=0; continue
  fi
  if [ "$mode" = 2 ]; then                    # ---- the time machine's picker ----
    if [ "$K" = "$ESC" ]; then
      K=$(dd bs=1 count=2 2>/dev/null <"$TTY")
      case "$K" in '[A') psel=$((psel - 1)) ;; '[B') psel=$((psel + 1)) ;; '') mode=0 ;; esac
    else
      case "$K" in
        "$NL"|"$CR")
          P=$(tui -v want=pick -v psel="$psel" -v td="$TD")
          case "$P" in
            '!'*) MSG="%baddate|$TD"; TD= ;;
            *) OLD=${WHEN:-$NOWD}; [ "$P" = - ] && WHEN= || WHEN=$P
               mode=0; TD=; MSG=; recount; warp "$OLD"; tick=0 ;;
          esac ;;
        k) psel=$((psel - 1)) ;;
        j) psel=$((psel + 1)) ;;
        [0-9-]) [ "${#TD}" -lt 10 ] && TD="$TD$K" ;;
        "$DEL"|"$BS") TD=${TD%?} ;;
        q|t) mode=0 ;;
      esac
    fi
    PN=11; [ -n "$WHEN" ] && PN=12
    [ "$psel" -ge "$PN" ] && psel=$((PN - 1))
    [ "$psel" -lt 0 ] && psel=0
    continue
  fi
  if [ "$mode" = 1 ]; then                    # ---- searching ----
    if [ "$K" = "$ESC" ]; then
      K=$(dd bs=1 count=2 2>/dev/null <"$TTY")
      case "$K" in '[A') ssel=$((ssel - 1)) ;; '[B') ssel=$((ssel + 1)) ;; '') mode=0; Q= ;; esac
    else
      case "$K" in
        "$NL"|"$CR")
          set -- $(tui -v want=hit -v q="$Q" -v sel="$ssel")
          if [ $# -eq 2 ] && [ "$1" = 9 ]; then go "$2"; continue; fi   # a photograph: open it, keep searching
          if [ $# -eq 2 ]; then tab=$1; eval "s$tab=$2"; fi
          mode=0; Q=; tick=0; continue ;;
        "$DEL"|"$BS") Q=$(drop_last "$Q"); ssel=0 ;;
        *)                                     # any printable character, in any script
          b=$(printf '%s' "$K" | od -An -tu1 | tr -d ' ')
          if [ "$b" -ge 240 ] 2>/dev/null; then K="$K$(dd bs=1 count=3 2>/dev/null <"$TTY")"
          elif [ "$b" -ge 224 ] 2>/dev/null; then K="$K$(dd bs=1 count=2 2>/dev/null <"$TTY")"
          elif [ "$b" -ge 192 ] 2>/dev/null; then K="$K$(dd bs=1 count=1 2>/dev/null <"$TTY")"
          fi
          if [ "$b" -ge 32 ] 2>/dev/null && [ "$b" != 127 ] && [ "$K" != '\' ] && [ "${#Q}" -lt 60 ]; then Q="$Q$K"; ssel=0; fi ;;
      esac
      NM=$(tui -v want=count -v q="$Q")
    fi
    [ "$ssel" -ge "${NM:-0}" ] && ssel=$((${NM:-0} - 1))
    [ "$ssel" -lt 0 ] && ssel=0
    continue
  fi
  [ -z "$MPID" ] && MSG=                       # a notice lasts until the next key
  if [ "$K" = "$ESC" ]; then
    K=$(dd bs=1 count=2 2>/dev/null <"$TTY")
    case "$K" in '[A') K=k ;; '[B') K=j ;; '[C') K=l ;; '[D') K=left ;; '[5') K=u ;; '[6') K=d ;; '') K=esc ;; *) K= ;; esac
  fi
  case "$K" in
    q|Q) break ;;
    /) mode=1; Q=; ssel=0; NM=0; continue ;;
    r|R)                                       # save the resume as Markdown, never over an existing file
      F="$PWD/@RESUME_FILE@.pdf"; n=1
      while [ -e "$F" ]; do n=$((n + 1)); F="$PWD/@RESUME_FILE@-$n.pdf"; done
      U="${WM_ORIGIN:-@ORIGIN@}/resume/@RESUME_FILE@.pdf"
      if command -v curl >/dev/null 2>&1 && curl -fsSL --max-time 20 "$U" -o "$F" 2>/dev/null; then MSG="%saved|$(basename "$F")|$(basename "$PWD")"
      elif command -v wget >/dev/null 2>&1 && wget -q -T 20 -O "$F" "$U" 2>/dev/null; then MSG="%saved|$(basename "$F")|$(basename "$PWD")"
      else
        [ -f "$F" ] && [ ! -s "$F" ] && rm -f "$F"            # an empty file from a failed download
        F="${F%.pdf}.md"                                      # offline: the same resume as Markdown
        if tui -v want=resume >"$F" 2>/dev/null; then MSG="%offline|$(basename "$F")"; else MSG='%nowrite'; fi
      fi
      continue ;;
    m|M) if [ -n "$MPID" ]; then music_off; MSG=; else music_on; fi; continue ;;
    -|_|+|=)                                   # music volume, 0-10; the music process reads the file
      case "$K" in -|_) [ "$VOL" -gt 0 ] && VOL=$((VOL - 1)) ;; *) [ "$VOL" -lt 10 ] && VOL=$((VOL + 1)) ;; esac
      [ -n "$MDIR" ] && [ -d "$MDIR" ] && echo "$VOL" >"$MDIR/vol"
      [ -z "$MPID" ] && MSG="%vol|$((VOL * 10))"
      continue ;;
    t) mode=2; psel=0; TD=; continue ;;
    T) if [ -n "$WHEN" ]; then OLD=$WHEN; WHEN=; recount; warp "$OLD"; tick=0; fi; continue ;;
    s) if [ "$SEASONS" = 1 ]; then SEASONS=0; MSG='%fxoff'; else SEASONS=1; MSG='%fxon'; fi; continue ;;
    D) mode=3; continue ;;
    L) if [ "$UTF" = 1 ]; then LANGC=$(next_lang "$LANGC"); else MSG='%utf'; fi; tick=0; continue ;;
    k) sel=$((sel - 1)) ;;
    j) sel=$((sel + 1)) ;;
    u) sel=$((sel - 8)) ;;
    d) sel=$((sel + 8)) ;;
    g) sel=0 ;;
    G) sel=$((n - 1)) ;;
    l|"$TAB") tab=$((tab % 5 + 1)); tick=0; continue ;;
    left) tab=$(((tab + 3) % 5 + 1)); tick=0; continue ;;
    h|'?') if [ "$LEG" = help ]; then LEG=short; else LEG=help; fi; continue ;;
    esc) [ "$LEG" = help ] && LEG=short; continue ;;
    1|2|3|4|5) tab=$K; tick=0; continue ;;
    "$NL"|"$CR"|o) U=$(tui -v want=url -v tab="$tab" -v sel="$sel"); [ -n "$U" ] && go "$U" ;;
    *) continue ;;
  esac
  [ "$sel" -ge "$n" ] && sel=$((n - 1))
  [ "$sel" -lt 0 ] && sel=0
  eval "s$tab=$sel"
done
